// rewrite-data.js — Sentence-transformation bank for the "Rewrite" tab.
// 200 typed questions across 25 structure types.
// Schema: { id, cat, catLabel, orig, stem, answer, accept[], vi, explanation }.
// Generated + verified by a 50-agent workflow; graded case/punctuation/
// contraction-insensitively (see js/rewrite.js _rwNormalize).

const REWRITE_QUESTIONS = [
  {"id":"rw-1","cat":"wish","catLabel":"Wish (điều ước không thật ở hiện tại)","orig":"Nam doesn't have a new bicycle, and he really wants one.","stem":"Nam wishes he","answer":"had a new bicycle","accept":["had a new bicycle","had a new bike"],"vi":"wish + Ved - điều ước trái thực tế ở hiện tại (have)","explanation":"Công thức: S + wish(es) + S + V-ed (quá khứ đơn) dùng để diễn tả điều ước trái với thực tế ở hiện tại. Câu gốc cho biết Nam không có xe đạp mới nhưng rất muốn có, nên ta lùi động từ 'have' về quá khứ đơn 'had'. Đáp án đầy đủ: Nam wishes he had a new bicycle."},
  {"id":"rw-2","cat":"wish","catLabel":"Wish (điều ước không thật ở hiện tại)","orig":"Minh doesn't live near the beach, but he loves swimming in the sea every morning.","stem":"Minh wishes he","answer":"lived near the beach","accept":["lived near the beach","lived close to the beach"],"vi":"wish + Ved - điều ước trái thực tế ở hiện tại (live)","explanation":"Công thức: S + wish(es) + S + V-ed để ước một điều không đúng với thực tế hiện tại. Minh không sống gần biển dù rất thích bơi ở biển mỗi sáng, nên ta lùi 'live' thành 'lived'. Đáp án đầy đủ: Minh wishes he lived near the beach."},
  {"id":"rw-3","cat":"wish","catLabel":"Wish (điều ước không thật ở hiện tại)","orig":"Our classroom doesn't have air conditioning, so we all feel uncomfortable during the hot summer months.","stem":"We wish our classroom","answer":"had air conditioning","accept":["had air conditioning","had an air conditioner"],"vi":"wish + Ved - điều ước trái thực tế ở hiện tại (have, về sự vật)","explanation":"Công thức: S + wish(es) + O + V-ed; wish có thể hướng đến một sự vật (ở đây là 'our classroom') chứ không nhất thiết là chính chủ ngữ. Lớp học không có máy lạnh khiến mọi người khó chịu vào mùa hè, nên ta lùi 'have' thành 'had'. Đáp án đầy đủ: We wish our classroom had air conditioning."},
  {"id":"rw-4","cat":"wish","catLabel":"Wish (điều ước không thật ở hiện tại)","orig":"Tom doesn't know how to play the guitar, although he really wants to join his friends' band.","stem":"Tom wishes he","answer":"knew how to play the guitar","accept":["knew how to play the guitar","knew how to play guitar"],"vi":"wish + Ved - điều ước trái thực tế ở hiện tại (know how to)","explanation":"Công thức: S + wish(es) + S + V-ed, áp dụng với cụm 'know how to + V'. Tom không biết chơi ghi-ta nên chưa thể vào ban nhạc của bạn bè, ta lùi 'know' thành 'knew'. Đáp án đầy đủ: Tom wishes he knew how to play the guitar."},
  {"id":"rw-5","cat":"wish","catLabel":"Wish (điều ước không thật ở hiện tại)","orig":"Lan can't reach the top shelf because she isn't tall enough, and this really annoys her.","stem":"Lan wishes she","answer":"were tall enough to reach the top shelf","accept":["were tall enough to reach the top shelf","was tall enough to reach the top shelf"],"vi":"wish + were - điều ước trái thực tế ở hiện tại (be + adj)","explanation":"Công thức: S + wish(es) + S + were + tính từ; với động từ 'to be', ta ưu tiên dùng 'were' cho mọi ngôi (giả định cách), 'was' cũng được chấp nhận trong văn nói thân mật. Lan không đủ cao nên không với tới kệ trên cùng, điều này khiến cô khó chịu. Đáp án đầy đủ: Lan wishes she were tall enough to reach the top shelf."},
  {"id":"rw-6","cat":"wish","catLabel":"Wish (điều ước không thật ở hiện tại)","orig":"Hoa is extremely busy with her studies this semester, and it makes her feel stressed all the time.","stem":"Hoa wishes she","answer":"were not so busy with her studies this semester","accept":["were not so busy with her studies this semester","was not so busy with her studies this semester","weren't so busy with her studies this semester","wasn't so busy with her studies this semester"],"vi":"wish + were not - điều ước phủ định ở hiện tại","explanation":"Công thức: S + wish(es) + S + were/was + not + tính từ; thêm 'not' ngay sau were/was để ước điều ngược lại theo hướng phủ định. Hoa hiện rất bận với việc học nên cảm thấy căng thẳng, do đó cô ước mình không bận như vậy. Đáp án đầy đủ: Hoa wishes she were not so busy with her studies this semester (= weren't...)."},
  {"id":"rw-7","cat":"wish","catLabel":"Wish (điều ước không thật ở hiện tại)","orig":"My father can't speak Japanese fluently, and he often regrets this when he travels for work.","stem":"My father wishes he","answer":"could speak Japanese fluently","accept":["could speak japanese fluently","could speak fluent japanese"],"vi":"wish + could - điều ước về khả năng ở hiện tại","explanation":"Công thức: S + wish(es) + S + could + V (nguyên mẫu), dùng khi ước về một khả năng không có ở hiện tại. Bố không nói được tiếng Nhật trôi chảy nên hay tiếc nuối mỗi khi đi công tác. Đáp án đầy đủ: My father wishes he could speak Japanese fluently."},
  {"id":"rw-8","cat":"wish","catLabel":"Wish (điều ước không thật ở hiện tại)","orig":"Mai's parents don't allow her to stay out after 9 p.m., and she thinks this rule is too strict for her age.","stem":"Mai wishes she","answer":"were allowed to stay out after 9 p.m.","accept":["were allowed to stay out after 9 p.m.","was allowed to stay out after 9 p.m.","were allowed to stay out later","was allowed to stay out later"],"vi":"wish + were + P2 - điều ước bị động ở hiện tại","explanation":"Công thức: S + wish(es) + S + were/was + P2 (dạng bị động sau wish), dùng để ước một quyền hạn không có ở hiện tại. Bố mẹ Mai không cho phép bạn ra ngoài sau 9 giờ tối và bạn thấy quy định này quá nghiêm khắc so với tuổi mình. Đáp án đầy đủ: Mai wishes she were allowed to stay out after 9 p.m. (was cũng được chấp nhận)."},
  {"id":"rw-9","cat":"unless","catLabel":"Unless ↔ If ... not","orig":"If you don't hurry up, you will miss the school bus.","stem":"Unless you","answer":"hurry up, you will miss the school bus","accept":["hurry up, you will miss the school bus","hurry up you will miss the school bus","hurry up, you'll miss the school bus","hurry up you'll miss the school bus"],"vi":"If...not = Unless — câu điều kiện loại 1 (phủ định → khẳng định)","explanation":"Công thức: If + S + don't/doesn't + V (nguyên mẫu), mệnh đề chính → Unless + S + V (bỏ 'not', chuyển động từ về dạng khẳng định), mệnh đề chính giữ nguyên. Câu gốc 'If you don't hurry up' mang nghĩa phủ định nên khi chuyển sang Unless ta bỏ 'don't' và dùng 'hurry up' ở dạng khẳng định. Đáp án đầy đủ: Unless you hurry up, you will miss the school bus."},
  {"id":"rw-10","cat":"unless","catLabel":"Unless ↔ If ... not","orig":"Unless she practices speaking English every day, she won't improve quickly.","stem":"If she","answer":"doesn't practice speaking English every day, she won't improve quickly","accept":["doesn't practice speaking english every day, she won't improve quickly","doesn't practice speaking english every day she won't improve quickly","does not practice speaking english every day, she won't improve quickly","does not practice speaking english every day she won't improve quickly"],"vi":"Unless = If...not — câu điều kiện loại 1 (khẳng định → phủ định)","explanation":"Công thức: Unless + S + V (khẳng định), mệnh đề chính → If + S + don't/doesn't + V (nguyên mẫu), mệnh đề chính giữ nguyên. Câu gốc 'Unless she practices' ở dạng khẳng định nên chuyển thành 'If she doesn't practice' (thêm trợ động từ phủ định 'doesn't' vì chủ ngữ 'she' số ít). Đáp án đầy đủ: If she doesn't practice speaking English every day, she won't improve quickly."},
  {"id":"rw-11","cat":"unless","catLabel":"Unless ↔ If ... not","orig":"If Tam doesn't finish his homework before dinner, he can't watch TV tonight.","stem":"Unless Tam","answer":"finishes his homework before dinner, he can't watch TV tonight","accept":["finishes his homework before dinner, he can't watch tv tonight","finishes his homework before dinner he can't watch tv tonight","finishes his homework before dinner, he cannot watch tv tonight","finishes his homework before dinner he cannot watch tv tonight"],"vi":"If...not = Unless — chia động từ theo chủ ngữ số ít","explanation":"Công thức: If + S + doesn't + V (nguyên mẫu) → Unless + S + V(s/es), vì đây là ngôi thứ ba số ít nên động từ thêm 's': 'finish' → 'finishes'. Mệnh đề chính giữ nguyên không đổi. Đáp án đầy đủ: Unless Tam finishes his homework before dinner, he can't watch TV tonight."},
  {"id":"rw-12","cat":"unless","catLabel":"Unless ↔ If ... not","orig":"Unless the weather improves, the football match will be cancelled.","stem":"If the weather","answer":"doesn't improve, the football match will be cancelled","accept":["doesn't improve, the football match will be cancelled","doesn't improve the football match will be cancelled","does not improve, the football match will be cancelled","doesn't improve, the football match will be canceled"],"vi":"Unless = If...not — chủ ngữ số ít dùng doesn't","explanation":"Công thức: Unless + S + V(s/es) → If + S + doesn't + V (nguyên mẫu). 'The weather' là danh từ số ít nên dùng trợ động từ 'doesn't' và động từ trở về nguyên mẫu 'improve'. Đáp án đầy đủ: If the weather doesn't improve, the football match will be cancelled."},
  {"id":"rw-13","cat":"unless","catLabel":"Unless ↔ If ... not","orig":"If you don't wear a helmet, you may get seriously injured in an accident.","stem":"Unless you","answer":"wear a helmet, you may get seriously injured in an accident","accept":["wear a helmet, you may get seriously injured in an accident","wear a helmet you may get seriously injured in an accident","wear a helmet, you might get seriously injured in an accident","wear a helmet you might get seriously injured in an accident"],"vi":"If...not = Unless — bỏ trợ động từ phủ định","explanation":"Công thức: If + S + don't + V → Unless + S + V (khẳng định). 'Don't wear' bỏ trợ động từ phủ định thành 'wear' vì chủ ngữ 'you'. Mệnh đề chính có động từ khuyết thiếu 'may' giữ nguyên. Đáp án đầy đủ: Unless you wear a helmet, you may get seriously injured in an accident."},
  {"id":"rw-14","cat":"unless","catLabel":"Unless ↔ If ... not","orig":"Unless we leave home right now, we will get stuck in the traffic jam.","stem":"If we","answer":"don't leave home right now, we will get stuck in the traffic jam","accept":["don't leave home right now, we will get stuck in the traffic jam","don't leave home right now we will get stuck in the traffic jam","do not leave home right now, we will get stuck in the traffic jam","don't leave home right now, we'll get stuck in the traffic jam"],"vi":"Unless = If...not — chủ ngữ we dùng don't","explanation":"Công thức: Unless + S + V → If + S + don't + V (nguyên mẫu). Chủ ngữ 'we' là số nhiều nên dùng trợ động từ phủ định 'don't', động từ 'leave' giữ nguyên dạng nguyên mẫu. Đáp án đầy đủ: If we don't leave home right now, we will get stuck in the traffic jam."},
  {"id":"rw-15","cat":"unless","catLabel":"Unless ↔ If ... not","orig":"If she doesn't apologize to her friend, their friendship might end.","stem":"Unless she","answer":"apologizes to her friend, their friendship might end","accept":["apologizes to her friend, their friendship might end","apologizes to her friend their friendship might end","apologises to her friend, their friendship might end","apologises to her friend their friendship might end"],"vi":"If...not = Unless — thêm s/es cho ngôi thứ 3 số ít","explanation":"Công thức: If + S + doesn't + V (nguyên mẫu) → Unless + S + V(s/es). Chủ ngữ 'she' số ít nên động từ 'apologize' phải thêm 's' thành 'apologizes'. Đáp án đầy đủ: Unless she apologizes to her friend, their friendship might end."},
  {"id":"rw-16","cat":"unless","catLabel":"Unless ↔ If ... not","orig":"Unless the government takes action soon, air pollution in the city will get worse.","stem":"If the government","answer":"doesn't take action soon, air pollution in the city will get worse","accept":["doesn't take action soon, air pollution in the city will get worse","doesn't take action soon air pollution in the city will get worse","does not take action soon, air pollution in the city will get worse","does not take action soon air pollution in the city will get worse"],"vi":"Unless = If...not — danh từ tập thể số ít","explanation":"Công thức: Unless + S + V(s/es) → If + S + doesn't + V (nguyên mẫu). 'The government' được xem là danh từ số ít nên dùng trợ động từ 'doesn't', động từ 'take' trở về nguyên mẫu. Đáp án đầy đủ: If the government doesn't take action soon, air pollution in the city will get worse."},
  {"id":"rw-17","cat":"although-despite","catLabel":"Although + mệnh đề → Despite/In spite of + danh từ/V-ing","orig":"Although the exam was difficult, most of the students passed it easily.","stem":"Despite","answer":"the difficult exam, most of the students passed it easily","accept":["the difficult exam, most of the students passed it easily","the difficult exam most of the students passed it easily","the difficult exam, most students passed it easily","the difficult exam most students passed it easily"],"vi":"Although + be + adj → Despite + adj + N — chuyển tính từ thành cụm danh từ","explanation":"Khi mệnh đề Although có dạng 'S + be + adj', ta chuyển tính từ đó thành cụm 'adj + danh từ' để đặt sau despite/in spite of, còn mệnh đề chính giữ nguyên. Ở câu này, 'the exam was difficult' trở thành 'the difficult exam'. Đáp án đầy đủ: Despite the difficult exam, most of the students passed it easily."},
  {"id":"rw-18","cat":"although-despite","catLabel":"Although + mệnh đề → Despite/In spite of + danh từ/V-ing","orig":"Although Tuan was exhausted after the marathon, he smiled proudly at the finish line.","stem":"Despite","answer":"being exhausted after the marathon, he smiled proudly at the finish line","accept":["being exhausted after the marathon, he smiled proudly at the finish line","being exhausted after the marathon he smiled proudly at the finish line","feeling exhausted after the marathon, he smiled proudly at the finish line","feeling exhausted after the marathon he smiled proudly at the finish line"],"vi":"Although (cùng chủ ngữ) + be + adj → Despite + being + adj","explanation":"Khi chủ ngữ của hai mệnh đề giống nhau và mệnh đề Although có dạng 'S + be + adj', ta rút gọn thành 'despite/in spite of + being + adj' (bỏ chủ ngữ, dùng V-ing của 'to be'). Ở đây 'Tuan was exhausted' chuyển thành 'being exhausted'. Đáp án đầy đủ: Despite being exhausted after the marathon, he smiled proudly at the finish line."},
  {"id":"rw-19","cat":"although-despite","catLabel":"Although + mệnh đề → Despite/In spite of + danh từ/V-ing","orig":"Although the traffic was terrible, Phong still arrived at the interview on time.","stem":"In spite of","answer":"the terrible traffic, Phong still arrived at the interview on time","accept":["the terrible traffic, phong still arrived at the interview on time","the terrible traffic phong still arrived at the interview on time","the terrible traffic, phong arrived at the interview on time","the terrible traffic phong arrived at the interview on time"],"vi":"Chủ ngữ khác nhau → Despite + adj + N (không dùng V-ing)","explanation":"Vì chủ ngữ hai mệnh đề khác nhau ('the traffic' và 'Phong'), ta không thể rút gọn bằng V-ing mà bắt buộc phải chuyển tính từ thành cụm danh từ 'adj + N'. Ở đây 'the traffic was terrible' thành 'the terrible traffic'. Đáp án đầy đủ: In spite of the terrible traffic, Phong still arrived at the interview on time."},
  {"id":"rw-20","cat":"although-despite","catLabel":"Although + mệnh đề → Despite/In spite of + danh từ/V-ing","orig":"Although Lan didn't have much experience in gardening, she managed to grow beautiful flowers in her garden.","stem":"Despite","answer":"not having much experience in gardening, she managed to grow beautiful flowers in her garden","accept":["not having much experience in gardening, she managed to grow beautiful flowers in her garden","not having much experience in gardening she managed to grow beautiful flowers in her garden","not having a lot of experience in gardening, she managed to grow beautiful flowers in her garden","not having a lot of experience in gardening she managed to grow beautiful flowers in her garden"],"vi":"Although + didn't have + N → Despite + not having + N","explanation":"Mệnh đề phủ định 'Although + S + didn't have + N' (cùng chủ ngữ với mệnh đề chính) chuyển thành 'despite/in spite of + not having + danh từ'. Ở đây 'Lan didn't have much experience in gardening' trở thành 'not having much experience in gardening'. Đáp án đầy đủ: Despite not having much experience in gardening, she managed to grow beautiful flowers in her garden."},
  {"id":"rw-21","cat":"although-despite","catLabel":"Although + mệnh đề → Despite/In spite of + danh từ/V-ing","orig":"Although the mountain road was dangerous, the rescue team reached the injured hikers quickly.","stem":"Despite","answer":"the danger of the mountain road, the rescue team reached the injured hikers quickly","accept":["the danger of the mountain road, the rescue team reached the injured hikers quickly","the danger of the mountain road the rescue team reached the injured hikers quickly","the dangerous mountain road, the rescue team reached the injured hikers quickly","the dangerous mountain road the rescue team reached the injured hikers quickly"],"vi":"Although + adj → Despite + the + danh từ trừu tượng + of + N","explanation":"Với tính từ có danh từ trừu tượng tương ứng (dangerous → danger), khi chủ ngữ hai mệnh đề khác nhau, ta có thể chuyển 'S + be + dangerous' thành 'the danger of + S' để dùng sau despite/in spite of. Ở đây 'the mountain road was dangerous' thành 'the danger of the mountain road'. Đáp án đầy đủ: Despite the danger of the mountain road, the rescue team reached the injured hikers quickly."},
  {"id":"rw-22","cat":"although-despite","catLabel":"Although + mệnh đề → Despite/In spite of + danh từ/V-ing","orig":"Although Mrs. Hoa didn't have much free time, she always cooked dinner for her family.","stem":"In spite of","answer":"not having much free time, she always cooked dinner for her family","accept":["not having much free time, she always cooked dinner for her family","not having much free time she always cooked dinner for her family","her lack of free time, she always cooked dinner for her family","her lack of free time she always cooked dinner for her family"],"vi":"Although + didn't have + N → In spite of + not having + N / lack of + N","explanation":"'Didn't have much free time' cùng chủ ngữ với mệnh đề chính nên được rút gọn thành cụm V-ing phủ định 'not having much free time' sau despite/in spite of (hoặc dùng danh từ 'her lack of free time'). Đáp án đầy đủ: In spite of not having much free time, she always cooked dinner for her family."},
  {"id":"rw-23","cat":"although-despite","catLabel":"Although + mệnh đề → Despite/In spite of + danh từ/V-ing","orig":"Although the youth choir had made several mistakes during rehearsals, they performed beautifully at the concert.","stem":"Despite","answer":"having made several mistakes during rehearsals, they performed beautifully at the concert","accept":["having made several mistakes during rehearsals, they performed beautifully at the concert","having made several mistakes during rehearsals they performed beautifully at the concert","having made several mistakes during rehearsals, the choir performed beautifully at the concert","having made several mistakes during rehearsals the choir performed beautifully at the concert"],"vi":"Although + had + PII (cùng chủ ngữ) → Despite + having + PII","explanation":"Khi hành động trong mệnh đề Although xảy ra TRƯỚC hành động chính (had + PII) và cùng chủ ngữ, ta dùng 'despite/in spite of + having + PII' để nhấn mạnh việc đã xảy ra/hoàn thành trước đó. Ở đây 'the youth choir had made several mistakes during rehearsals' thành 'having made several mistakes during rehearsals'. Đáp án đầy đủ: Despite having made several mistakes during rehearsals, they performed beautifully at the concert."},
  {"id":"rw-24","cat":"although-despite","catLabel":"Although + mệnh đề → Despite/In spite of + danh từ/V-ing","orig":"Although Duc hadn't practiced speaking English for a long time, he communicated confidently with the foreign tourists at the museum.","stem":"In spite of","answer":"not having practiced speaking English for a long time, he communicated confidently with the foreign tourists at the museum","accept":["not having practiced speaking english for a long time, he communicated confidently with the foreign tourists at the museum","not having practiced speaking english for a long time he communicated confidently with the foreign tourists at the museum","not having practised speaking english for a long time, he communicated confidently with the foreign tourists at the museum","not having practised speaking english for a long time he communicated confidently with the foreign tourists at the museum"],"vi":"Although + hadn't + PII → In spite of + not having + PII","explanation":"Câu vừa phủ định vừa chỉ hành động xảy ra trước và kéo dài đến một mốc trong quá khứ ('hadn't practiced ... for a long time'), cùng chủ ngữ với mệnh đề chính nên chuyển thành 'not having + PII' sau despite/in spite of. Đáp án đầy đủ: In spite of not having practiced speaking English for a long time, he communicated confidently with the foreign tourists at the museum."},
  {"id":"rw-25","cat":"despite-although","catLabel":"Despite + danh từ → Although + mệnh đề","orig":"Despite the heavy rain, the football match continued without any delay.","stem":"Although it","answer":"rained heavily, the football match continued without any delay","accept":["rained heavily, the football match continued without any delay","rained heavily the football match continued without any delay","rained hard, the football match continued without any delay","rained heavily, the match continued without any delay","rained heavily, the football match continued without delay"],"vi":"Despite + danh từ → Although + mệnh đề (nhượng bộ)","explanation":"'Despite/In spite of + danh từ' và 'Although/Though + mệnh đề (S+V)' đều diễn tả sự tương phản, có thể thay thế cho nhau. Ở đây cụm danh từ 'the heavy rain' được chuyển thành mệnh đề đầy đủ 'it rained heavily' (dùng chủ ngữ giả 'it' vì rain là hiện tượng thời tiết, chia quá khứ để khớp với 'continued'). Đáp án đầy đủ: Although it rained heavily, the football match continued without any delay."},
  {"id":"rw-26","cat":"despite-although","catLabel":"Despite + danh từ → Although + mệnh đề","orig":"Despite his young age, he can speak three languages fluently.","stem":"Although he","answer":"is young, he can speak three languages fluently","accept":["is young, he can speak three languages fluently","is young he can speak three languages fluently","is still young, he can speak three languages fluently"],"vi":"Despite + danh từ → Although + mệnh đề (nhượng bộ)","explanation":"Cấu trúc 'Despite + N' chuyển sang 'Although + S + V' bằng cách biến danh từ thành mệnh đề có chủ ngữ - động từ tương ứng. 'His young age' → 'he is young', giữ thì hiện tại vì vế sau dùng 'can speak' diễn tả khả năng ở hiện tại. Đáp án đầy đủ: Although he is young, he can speak three languages fluently."},
  {"id":"rw-27","cat":"despite-although","catLabel":"Despite + danh từ → Although + mệnh đề","orig":"Despite the difficulty of the exam, most students passed with good marks.","stem":"Although the exam","answer":"was difficult, most students passed with good marks","accept":["was difficult, most students passed with good marks","was difficult most students passed with good marks","was hard, most students passed with good marks","was difficult, most students passed","was hard, most students passed"],"vi":"Despite + danh từ → Although + mệnh đề (nhượng bộ)","explanation":"Khi chuyển 'Despite the difficulty of the exam' sang 'Although', ta lấy danh từ trung tâm ('the exam') làm chủ ngữ và đổi 'difficulty' thành tính từ 'difficult'. Vì mệnh đề sau ở quá khứ ('passed'), mệnh đề 'Although' cũng chia quá khứ: 'the exam was difficult'. Đáp án đầy đủ: Although the exam was difficult, most students passed with good marks."},
  {"id":"rw-28","cat":"despite-although","catLabel":"Despite + danh từ → Although + mệnh đề","orig":"Despite her lack of experience, she got the job at the new company.","stem":"Although she","answer":"lacked experience, she got the job at the new company","accept":["lacked experience, she got the job at the new company","lacked experience she got the job at the new company","had no experience, she got the job at the new company","didn't have experience, she got the job at the new company","did not have experience, she got the job at the new company"],"vi":"Despite + danh từ → Although + mệnh đề (nhượng bộ)","explanation":"Cụm 'her lack of experience' được viết lại thành mệnh đề bằng cách chuyển danh từ 'lack' thành động từ 'lacked': 'she lacked experience'. Thì của mệnh đề nhượng bộ phải khớp với mệnh đề chính ở quá khứ ('got'). Đáp án đầy đủ: Although she lacked experience, she got the job at the new company."},
  {"id":"rw-29","cat":"despite-although","catLabel":"Despite + danh từ → Although + mệnh đề","orig":"Despite the high price of the laptop, many students still want to buy it.","stem":"Although the laptop","answer":"is expensive, many students still want to buy it","accept":["is expensive, many students still want to buy it","is expensive many students still want to buy it","is expensive, many students still want to buy the laptop"],"vi":"Despite + danh từ → Although + mệnh đề (nhượng bộ)","explanation":"'The high price of the laptop' mang nghĩa tương đương tính từ 'expensive', nên khi chuyển sang 'Although' ta dùng chủ ngữ 'the laptop' + 'is expensive' (thì hiện tại, khớp với 'want' ở mệnh đề chính). Đáp án đầy đủ: Although the laptop is expensive, many students still want to buy it."},
  {"id":"rw-30","cat":"despite-although","catLabel":"Despite + danh từ → Although + mệnh đề","orig":"Despite the poor condition of the road, drivers use it every day to save time.","stem":"Although the road","answer":"is in poor condition, drivers use it every day to save time","accept":["is in poor condition, drivers use it every day to save time","is in poor condition drivers use it every day to save time","is in bad condition, drivers use it every day to save time","is in poor condition, drivers use it every day"],"vi":"Despite + danh từ → Although + mệnh đề (nhượng bộ)","explanation":"Danh từ 'the poor condition of the road' chuyển thành mệnh đề 'the road is in poor condition', giữ nguyên thì hiện tại vì mệnh đề chính dùng 'use' (thói quen). Đáp án đầy đủ: Although the road is in poor condition, drivers use it every day to save time."},
  {"id":"rw-31","cat":"despite-although","catLabel":"Despite + danh từ → Although + mệnh đề","orig":"Despite the success of the new policy, some citizens still complain about it.","stem":"Although the new policy","answer":"is successful, some citizens still complain about it","accept":["is successful, some citizens still complain about it","is successful some citizens still complain about it","has been successful, some citizens still complain about it","is a success, some citizens still complain about it"],"vi":"Despite + danh từ → Although + mệnh đề (nhượng bộ)","explanation":"'The success of the new policy' → chủ ngữ 'the new policy' + tính từ 'successful': 'the new policy is successful', thì hiện tại khớp với 'complain'. Đáp án đầy đủ: Although the new policy is successful, some citizens still complain about it."},
  {"id":"rw-32","cat":"despite-although","catLabel":"Despite + danh từ → Although + mệnh đề","orig":"Despite the seriousness of her illness, she still attended the important meeting.","stem":"Although her illness","answer":"was serious, she still attended the important meeting","accept":["was serious, she still attended the important meeting","was serious she still attended the important meeting","was serious, she still went to the important meeting","was serious she still went to the important meeting"],"vi":"Despite + danh từ → Although + mệnh đề (nhượng bộ)","explanation":"Danh từ trừu tượng 'the seriousness of her illness' chuyển thành mệnh đề 'her illness was serious' (đổi 'seriousness' thành tính từ 'serious'), chia quá khứ để khớp với 'attended'. Đáp án đầy đủ: Although her illness was serious, she still attended the important meeting."},
  {"id":"rw-33","cat":"so-such","catLabel":"So + adj + that ↔ Such + (a/an) + adj + noun + that","orig":"The soup was so hot that Mai couldn't eat it right away.","stem":"It was such","answer":"hot soup that Mai couldn't eat it right away","accept":["hot soup that mai couldn't eat it right away","hot soup that mai could not eat it right away"],"vi":"So + adj + that ↔ Such + adj + N + that — danh từ không đếm được","explanation":"Công thức: So + adj + that = Such + (a/an) + adj + N + that, hai cấu trúc cùng nghĩa 'quá... đến nỗi...'. Vì 'soup' là danh từ không đếm được nên không dùng a/an, ta ghép trực tiếp 'such' + tính từ 'hot' + danh từ 'soup'. Đáp án đầy đủ: It was such hot soup that Mai couldn't eat it right away."},
  {"id":"rw-34","cat":"so-such","catLabel":"So + adj + that ↔ Such + (a/an) + adj + noun + that","orig":"The exam was so difficult that many students failed.","stem":"It was such","answer":"a difficult exam that many students failed","accept":["a difficult exam that many students failed","a difficult exam that many students failed it"],"vi":"So + adj + that ↔ Such + a/an + adj + N + that — danh từ đếm được số ít","explanation":"Công thức: So + adj + that = Such + a/an + adj + N + that. 'Exam' là danh từ đếm được số ít, tính từ 'difficult' bắt đầu bằng phụ âm nên dùng 'a': 'such a difficult exam'. Đáp án đầy đủ: It was such a difficult exam that many students failed."},
  {"id":"rw-35","cat":"so-such","catLabel":"So + adj + that ↔ Such + (a/an) + adj + noun + that","orig":"The rain was so heavy that the football match had to be cancelled.","stem":"It was such","answer":"heavy rain that the football match had to be cancelled","accept":["heavy rain that the football match had to be cancelled","heavy rain that the match had to be cancelled"],"vi":"So + adj + that ↔ Such + adj + N + that — danh từ không đếm được","explanation":"Công thức: So + adj + that = Such + (a/an) + adj + N + that. 'Rain' là danh từ không đếm được nên không thêm a/an sau 'such': 'such heavy rain'. Đáp án đầy đủ: It was such heavy rain that the football match had to be cancelled."},
  {"id":"rw-36","cat":"so-such","catLabel":"So + adj + that ↔ Such + (a/an) + adj + noun + that","orig":"The photos Lan took at the beach were so blurry that she couldn't use any of them for the school project.","stem":"They were such","answer":"blurry photos that she couldn't use any of them for the school project","accept":["blurry photos that she couldn't use any of them for the school project","blurry photos that she could not use any of them for the school project"],"vi":"So + adj + that ↔ Such + adj + Ns + that — danh từ số nhiều, không thêm a/an","explanation":"Công thức: So + adj + that = Such + (a/an) + adj + N(s) + that. Vì chủ ngữ 'the photos' là danh từ số nhiều nên không thêm a/an, chỉ cần 'such' + tính từ 'blurry' + danh từ số nhiều 'photos'; chủ ngữ chuyển thành 'They'. Đáp án đầy đủ: They were such blurry photos that she couldn't use any of them for the school project."},
  {"id":"rw-37","cat":"so-such","catLabel":"So + adj + that ↔ Such + (a/an) + adj + noun + that","orig":"The story was so interesting that the children begged their mother to read it again.","stem":"It was such","answer":"an interesting story that the children begged their mother to read it again","accept":["an interesting story that the children begged their mother to read it again","an interesting story that the kids begged their mother to read it again"],"vi":"So + adj + that ↔ Such + an + adj + N + that — tính từ bắt đầu bằng nguyên âm","explanation":"Công thức: So + adj + that = Such + a/an + adj + N + that. Vì tính từ 'interesting' bắt đầu bằng âm nguyên âm nên dùng 'an' thay vì 'a': 'such an interesting story'. Đáp án đầy đủ: It was such an interesting story that the children begged their mother to read it again."},
  {"id":"rw-38","cat":"so-such","catLabel":"So + adj + that ↔ Such + (a/an) + adj + noun + that","orig":"The hike up the mountain was so tiring that Minh needed two full days to recover.","stem":"It was such","answer":"a tiring hike that Minh needed two full days to recover","accept":["a tiring hike that minh needed two full days to recover","a tiring hike that minh needed two whole days to recover"],"vi":"So + adj + that ↔ Such + a/an + adj + N + that — tính từ dạng V-ing chỉ cảm giác","explanation":"Công thức: So + adj + that = Such + a/an + adj + N + that. 'Hike' là danh từ đếm được số ít, tính từ 'tiring' bắt đầu bằng phụ âm nên dùng 'a': 'such a tiring hike'. Đáp án đầy đủ: It was such a tiring hike that Minh needed two full days to recover."},
  {"id":"rw-39","cat":"so-such","catLabel":"So + adj + that ↔ Such + (a/an) + adj + noun + that","orig":"The traffic jam was so long that hundreds of vehicles were stuck for over two hours.","stem":"It was such","answer":"a long traffic jam that hundreds of vehicles were stuck for over two hours","accept":["a long traffic jam that hundreds of vehicles were stuck for over two hours","a long traffic jam that hundreds of vehicles were stuck for more than two hours"],"vi":"So + adj + that ↔ Such + a/an + adj + N + that — cụm danh từ ghép (compound noun)","explanation":"Công thức: So + adj + that = Such + a/an + adj + N + that, áp dụng được cả với danh từ ghép như 'traffic jam'. Vì 'traffic jam' đếm được, số ít, và tính từ 'long' bắt đầu bằng phụ âm nên dùng 'a': 'such a long traffic jam'. Đáp án đầy đủ: It was such a long traffic jam that hundreds of vehicles were stuck for over two hours."},
  {"id":"rw-40","cat":"so-such","catLabel":"So + adj + that ↔ Such + (a/an) + adj + noun + that","orig":"The news was so shocking that nobody at the meeting could believe it at first.","stem":"It was such","answer":"shocking news that nobody at the meeting could believe it at first","accept":["shocking news that nobody at the meeting could believe it at first","shocking news that no one at the meeting could believe it at first"],"vi":"So + adj + that ↔ Such + adj + N + that — 'news' luôn là danh từ không đếm được","explanation":"Công thức: So + adj + that = Such + (a/an) + adj + N + that. Lưu ý 'news' tuy có đuôi -s nhưng luôn là danh từ không đếm được (số ít) nên không dùng a/an: 'such shocking news'. Đáp án đầy đủ: It was such shocking news that nobody at the meeting could believe it at first."},
  {"id":"rw-41","cat":"too-enough","catLabel":"Too + adj + to ↔ Not + adj + enough + to","orig":"The box was too heavy for Minh to carry by himself.","stem":"The box was not","answer":"light enough for Minh to carry by himself","accept":["light enough for minh to carry by himself","light enough for minh to carry alone","light enough for minh to carry it by himself","light enough for minh to carry"],"vi":"too + adj >< not + adj trái nghĩa + enough — heavy >< light","explanation":"Công thức: S + tobe + too + adj + (for O) + to V = S + tobe + not + adj (trái nghĩa) + enough + (for O) + to V, hai câu luôn cùng nghĩa 'không đủ khả năng để làm gì'. Ở câu gốc 'too heavy' (quá nặng) khiến Minh không tự mang nổi, nên khi viết lại ta dùng tính từ trái nghĩa 'light' (nhẹ) ở dạng phủ định 'not light enough'. Đáp án đầy đủ: The box was not light enough for Minh to carry by himself."},
  {"id":"rw-42","cat":"too-enough","catLabel":"Too + adj + to ↔ Not + adj + enough + to","orig":"My grandmother is too old to climb the stairs quickly.","stem":"My grandmother is not","answer":"young enough to climb the stairs quickly","accept":["young enough to climb the stairs quickly","young enough to climb the stairs fast","young enough to climb up the stairs quickly","young enough to climb the stairs"],"vi":"too + adj >< not + adj trái nghĩa + enough — old >< young","explanation":"Công thức chuyển đổi: too + adj + to V = not + adj trái nghĩa + enough + to V, vì 'quá già để làm gì nhanh' cũng có nghĩa là 'không đủ trẻ để làm việc đó nhanh'. Ở đây 'old' được thay bằng tính từ trái nghĩa 'young', giữ nguyên phần còn lại của câu 'to climb the stairs quickly'. Đáp án đầy đủ: My grandmother is not young enough to climb the stairs quickly."},
  {"id":"rw-43","cat":"too-enough","catLabel":"Too + adj + to ↔ Not + adj + enough + to","orig":"Lan is too short to reach the top shelf in the kitchen.","stem":"Lan is not","answer":"tall enough to reach the top shelf in the kitchen","accept":["tall enough to reach the top shelf in the kitchen","tall enough to reach the top shelf","tall enough to reach the top shelf in the kitchen alone"],"vi":"too + adj >< not + adj trái nghĩa + enough — short >< tall","explanation":"Áp dụng công thức too + adj + to V = not + adj trái nghĩa + enough + to V: 'too short' (quá thấp) chuyển thành 'not tall enough' (không đủ cao), phần mục đích 'to reach the top shelf in the kitchen' được giữ nguyên vì không đổi nghĩa. Học sinh cần nhớ đổi đúng tính từ trái nghĩa chứ không giữ nguyên 'short'. Đáp án đầy đủ: Lan is not tall enough to reach the top shelf in the kitchen."},
  {"id":"rw-44","cat":"too-enough","catLabel":"Too + adj + to ↔ Not + adj + enough + to","orig":"The final exam was too difficult for most students to finish on time.","stem":"The final exam was not","answer":"easy enough for most students to finish on time","accept":["easy enough for most students to finish on time","easy enough for most students to finish","easy enough for most students to complete on time"],"vi":"too + adj >< not + adj trái nghĩa + enough — difficult >< easy","explanation":"Công thức: S + tobe + too + adj + for O + to V = S + tobe + not + adj trái nghĩa + enough + for O + to V. 'Too difficult' (quá khó) mang nghĩa 'not easy enough' (không đủ dễ), cụm 'for most students to finish on time' vẫn giữ nguyên vì nó chỉ đối tượng và mục đích. Đáp án đầy đủ: The final exam was not easy enough for most students to finish on time."},
  {"id":"rw-45","cat":"too-enough","catLabel":"Too + adj + to ↔ Not + adj + enough + to","orig":"This laptop is too expensive for Nam to buy right now.","stem":"This laptop is not","answer":"cheap enough for Nam to buy right now","accept":["cheap enough for nam to buy right now","cheap enough for nam to buy now","cheap enough for nam to buy"],"vi":"too + adj >< not + adj trái nghĩa + enough — expensive >< cheap","explanation":"Chuyển đổi theo công thức too + adj + for O + to V = not + adj trái nghĩa + enough + for O + to V. 'Too expensive' (quá đắt) tương đương 'not cheap enough' (không đủ rẻ), giữ nguyên 'for Nam to buy right now'. Đáp án đầy đủ: This laptop is not cheap enough for Nam to buy right now."},
  {"id":"rw-46","cat":"too-enough","catLabel":"Too + adj + to ↔ Not + adj + enough + to","orig":"The street outside our house is too noisy for me to study at night.","stem":"The street outside our house is not","answer":"quiet enough for me to study at night","accept":["quiet enough for me to study at night","quiet enough for me to study","quiet enough for me to study during the night"],"vi":"too + adj >< not + adj trái nghĩa + enough — noisy >< quiet","explanation":"Vẫn là công thức too + adj + for O + to V = not + adj trái nghĩa + enough + for O + to V. 'Too noisy' (quá ồn) được diễn đạt lại bằng 'not quiet enough' (không đủ yên tĩnh), phần 'for me to study at night' không đổi vì đó là mục đích và thời gian. Đáp án đầy đủ: The street outside our house is not quiet enough for me to study at night."},
  {"id":"rw-47","cat":"too-enough","catLabel":"Too + adj + to ↔ Not + adj + enough + to","orig":"The Wi-Fi connection here is too slow for us to watch online videos smoothly.","stem":"The Wi-Fi connection here is not","answer":"fast enough for us to watch online videos smoothly","accept":["fast enough for us to watch online videos smoothly","fast enough for us to watch online videos","fast enough for us to watch videos online smoothly"],"vi":"too + adj >< not + adj trái nghĩa + enough — slow >< fast","explanation":"Áp dụng too + adj + for O + to V = not + adj trái nghĩa + enough + for O + to V: 'too slow' (quá chậm) chuyển thành 'not fast enough' (không đủ nhanh), câu vẫn giữ cụm mục đích dài 'to watch online videos smoothly'. Chú ý đổi đúng tính từ trái nghĩa, không thêm 'not' trước 'slow'. Đáp án đầy đủ: The Wi-Fi connection here is not fast enough for us to watch online videos smoothly."},
  {"id":"rw-48","cat":"too-enough","catLabel":"Too + adj + to ↔ Not + adj + enough + to","orig":"After the marathon, the runner was too weak to stand on his own feet.","stem":"After the marathon, the runner was not","answer":"strong enough to stand on his own feet","accept":["strong enough to stand on his own feet","strong enough to stand on his own two feet","strong enough to stand up on his own feet","strong enough to stand by himself"],"vi":"too + adj >< not + adj trái nghĩa + enough — weak >< strong","explanation":"Công thức too + adj + to V = not + adj trái nghĩa + enough + to V vẫn áp dụng dù câu có mệnh đề trạng ngữ thời gian 'After the marathon' ở đầu câu — phần này giữ nguyên vị trí khi viết lại. 'Too weak' (quá yếu) chuyển thành 'not strong enough' (không đủ khỏe), giữ nguyên 'to stand on his own feet'. Đáp án đầy đủ: After the marathon, the runner was not strong enough to stand on his own feet."},
  {"id":"rw-49","cat":"passive","catLabel":"Câu bị động (hiện tại/quá khứ đơn)","orig":"Nam waters the plants in the garden every day.","stem":"The plants in the garden","answer":"are watered by Nam every day","accept":["are watered by nam every day","are watered every day by nam"],"vi":"Bị động thì hiện tại đơn (S + is/am/are + V3/ed)","explanation":"Công thức: chủ động \"S + V(s/es) + O\" chuyển thành bị động \"O + am/is/are + V3/ed (+ by + S)\". Tân ngữ \"the plants in the garden\" số nhiều làm chủ ngữ mới nên dùng \"are watered\"; vì Nam là tác nhân cụ thể (không phải đại từ chung chung) nên phải giữ \"by Nam\" để không mất thông tin, trạng từ \"every day\" đứng cuối câu. Đáp án đầy đủ: \"The plants in the garden are watered by Nam every day.\""},
  {"id":"rw-50","cat":"passive","catLabel":"Câu bị động (hiện tại/quá khứ đơn)","orig":"The workers built this bridge in 2015.","stem":"This bridge","answer":"was built by the workers in 2015","accept":["was built by the workers in 2015","was built in 2015 by the workers"],"vi":"Bị động thì quá khứ đơn (S + was/were + V3/ed)","explanation":"Công thức: \"S + V2/ed + O\" chuyển thành \"O + was/were + V3/ed (+ by + S)\". Chủ ngữ mới \"this bridge\" số ít nên dùng \"was built\"; vì \"the workers\" là tác nhân cụ thể (có \"the\", khác với đại từ chung chung như people/someone) nên phải giữ lại \"by the workers\" để bảo toàn đầy đủ nghĩa câu gốc. Đáp án đầy đủ: \"This bridge was built by the workers in 2015.\""},
  {"id":"rw-51","cat":"passive","catLabel":"Câu bị động (hiện tại/quá khứ đơn)","orig":"People speak two languages in Singapore.","stem":"Two languages","answer":"are spoken in Singapore","accept":["are spoken in singapore","are spoken in singapore by people"],"vi":"Bị động hiện tại đơn — lược bỏ tác nhân chung chung (people)","explanation":"Khi chủ ngữ chủ động là từ chung chung như \"people/someone/they\", ta thường bỏ \"by + tác nhân\" trong câu bị động vì không mang thêm thông tin. Công thức: \"People + V(s/es) + O\" chuyển thành \"O + are/is + V3/ed\". Chủ ngữ mới \"two languages\" số nhiều nên dùng \"are spoken\". Đáp án đầy đủ: \"Two languages are spoken in Singapore.\""},
  {"id":"rw-52","cat":"passive","catLabel":"Câu bị động (hiện tại/quá khứ đơn)","orig":"A famous chef cooked this special dish for the wedding party last night.","stem":"This special dish","answer":"was cooked by a famous chef for the wedding party last night","accept":["was cooked by a famous chef for the wedding party last night","was cooked for the wedding party by a famous chef last night","was cooked by a famous chef last night for the wedding party"],"vi":"Bị động quá khứ đơn có nhiều trạng ngữ","explanation":"Công thức: \"S + V2/ed + O + trạng ngữ\" chuyển thành \"O + was/were + V3/ed + by + S + trạng ngữ\". Tác nhân \"a famous chef\" là thông tin quan trọng nên giữ lại \"by a famous chef\"; các trạng ngữ \"for the wedding party\" và \"last night\" đứng sau và có thể đổi thứ tự cho nhau. Đáp án đầy đủ: \"This special dish was cooked by a famous chef for the wedding party last night.\""},
  {"id":"rw-53","cat":"passive","catLabel":"Câu bị động (hiện tại/quá khứ đơn)","orig":"Thousands of tourists visit this ancient temple every year.","stem":"This ancient temple","answer":"is visited by thousands of tourists every year","accept":["is visited by thousands of tourists every year","is visited every year by thousands of tourists"],"vi":"Bị động hiện tại đơn với chủ ngữ có lượng từ","explanation":"Công thức: \"S (số nhiều) + V(s/es) + O\" chuyển thành \"O + is/am/are + V3/ed + by + S\". Chủ ngữ mới \"this ancient temple\" số ít nên bị động chia \"is visited\"; tác nhân \"thousands of tourists\" được giữ lại vì là thông tin chính. Đáp án đầy đủ: \"This ancient temple is visited by thousands of tourists every year.\""},
  {"id":"rw-54","cat":"passive","catLabel":"Câu bị động (hiện tại/quá khứ đơn)","orig":"The teacher gave the students a difficult test last Monday.","stem":"A difficult test","answer":"was given to the students by the teacher last Monday","accept":["was given to the students by the teacher last monday","was given by the teacher to the students last monday"],"vi":"Bị động quá khứ đơn — động từ có 2 tân ngữ (give sb sth)","explanation":"Với động từ có 2 tân ngữ như \"give sb sth\", có thể chọn 1 trong 2 tân ngữ làm chủ ngữ bị động; đề đã cho sẵn chủ ngữ mới là \"a difficult test\" nên tân ngữ còn lại \"the students\" phải thêm giới từ \"to\": \"O + was/were + V3/ed + to + tân ngữ còn lại + by + S\". Vì \"the teacher\" là tác nhân cụ thể nên giữ \"by the teacher\" để bảo toàn đầy đủ nghĩa câu gốc. Đáp án đầy đủ: \"A difficult test was given to the students by the teacher last Monday.\""},
  {"id":"rw-55","cat":"passive","catLabel":"Câu bị động (hiện tại/quá khứ đơn)","orig":"Skilled craftsmen make these wooden chairs carefully in a small village.","stem":"These wooden chairs","answer":"are made carefully in a small village by skilled craftsmen","accept":["are made carefully in a small village by skilled craftsmen","are made carefully by skilled craftsmen in a small village","are made by skilled craftsmen carefully in a small village"],"vi":"Bị động hiện tại đơn với trạng từ cách thức và tác nhân","explanation":"Công thức: \"S + V(s/es) + O + trạng từ + nơi chốn\" chuyển thành \"O + is/are + V3/ed + trạng từ + nơi chốn + by + S\". Động từ \"make\" có quá khứ phân từ bất quy tắc là \"made\"; tác nhân \"skilled craftsmen\" được giữ lại vì là thông tin chính của câu. Đáp án đầy đủ: \"These wooden chairs are made carefully in a small village by skilled craftsmen.\""},
  {"id":"rw-56","cat":"passive","catLabel":"Câu bị động (hiện tại/quá khứ đơn)","orig":"A young poet wrote this beautiful song for his hometown in 2010.","stem":"This beautiful song","answer":"was written by a young poet for his hometown in 2010","accept":["was written by a young poet for his hometown in 2010","was written for his hometown by a young poet in 2010","was written by a young poet in 2010 for his hometown"],"vi":"Bị động quá khứ đơn với động từ bất quy tắc (write - wrote - written)","explanation":"Công thức: \"S + V2 + O + for + N + trạng ngữ\" chuyển thành \"O + was/were + V3 + by + S + for + N + trạng ngữ\". Động từ \"write\" có quá khứ phân từ bất quy tắc là \"written\" (không phải \"writed\"); các cụm \"by a young poet\", \"for his hometown\", \"in 2010\" đứng sau động từ và có thể đổi vị trí cho nhau. Đáp án đầy đủ: \"This beautiful song was written by a young poet for his hometown in 2010.\""},
  {"id":"rw-57","cat":"reported-statement","catLabel":"Câu tường thuật (câu kể)","orig":"\"I feed my cat every morning,\" Nam said.","stem":"Nam said that","answer":"he fed his cat every morning","accept":["he fed his cat every morning","he fed his cat every morning.","he fed his cat each morning"],"vi":"Reported speech — hiện tại đơn → quá khứ đơn","explanation":"Khi tường thuật lại một câu kể ở thì hiện tại đơn, ta lùi thì động từ về quá khứ đơn (feed → fed) và đổi đại từ/tính từ sở hữu cho phù hợp người nói (I → he, my → his). Công thức: S + said (that) + S' + V2/V-ed... Áp dụng vào câu này ta có: 'Nam said that he fed his cat every morning.'"},
  {"id":"rw-58","cat":"reported-statement","catLabel":"Câu tường thuật (câu kể)","orig":"\"I can speak three languages,\" Mai said.","stem":"Mai said that","answer":"she could speak three languages","accept":["she could speak three languages","she could speak three languages.","she was able to speak three languages"],"vi":"Reported speech — can → could","explanation":"Động từ khuyết thiếu 'can' luôn lùi thành 'could' khi tường thuật lại lời nói ở thì quá khứ; các phần còn lại của câu giữ nguyên vì không có trạng từ thời gian/nơi chốn cần đổi. Công thức: can → could. Đáp án: 'Mai said that she could speak three languages.'"},
  {"id":"rw-59","cat":"reported-statement","catLabel":"Câu tường thuật (câu kể)","orig":"\"I am cooking dinner now,\" my mother said.","stem":"My mother said that","answer":"she was cooking dinner then","accept":["she was cooking dinner then","she was cooking dinner then.","she was cooking dinner at that time"],"vi":"Reported speech — hiện tại tiếp diễn → quá khứ tiếp diễn","explanation":"Thì hiện tại tiếp diễn trong câu trực tiếp lùi về quá khứ tiếp diễn khi tường thuật (am cooking → was cooking); đồng thời trạng từ chỉ thời gian 'now' phải đổi thành 'then' vì thời điểm nói đã trở thành quá khứ. Công thức: am/is/are + V-ing → was/were + V-ing. Đáp án đầy đủ: 'My mother said that she was cooking dinner then.'"},
  {"id":"rw-60","cat":"reported-statement","catLabel":"Câu tường thuật (câu kể)","orig":"\"I must finish this report today,\" Mr. Khoa said.","stem":"Mr. Khoa said that","answer":"he had to finish that report that day","accept":["he had to finish that report that day","he had to finish that report that day.","he had to finish that report the same day"],"vi":"Reported speech — must → had to","explanation":"Động từ khuyết thiếu 'must' chỉ nghĩa vụ nhất thời thường được lùi thành 'had to' trong câu tường thuật; tính từ chỉ định 'this' đổi thành 'that' và trạng từ 'today' đổi thành 'that day' vì không còn là ngày nói. Đáp án: 'Mr. Khoa said that he had to finish that report that day.'"},
  {"id":"rw-61","cat":"reported-statement","catLabel":"Câu tường thuật (câu kể)","orig":"\"I have finished my homework,\" Tom said.","stem":"Tom said that","answer":"he had finished his homework","accept":["he had finished his homework","he had finished his homework.","he'd finished his homework"],"vi":"Reported speech — hiện tại hoàn thành → quá khứ hoàn thành","explanation":"Vì động từ tường thuật 'said' ở quá khứ, thì hiện tại hoàn thành trong câu trực tiếp phải lùi thành quá khứ hoàn thành (have finished → had finished). Công thức: have/has + P2 → had + P2. Đáp án mẫu: 'Tom said that he had finished his homework.'"},
  {"id":"rw-62","cat":"reported-statement","catLabel":"Câu tường thuật (câu kể)","orig":"\"I visited my grandmother yesterday,\" Hoa said.","stem":"Hoa said that","answer":"she had visited her grandmother the day before","accept":["she had visited her grandmother the day before","she had visited her grandmother the day before.","she had visited her grandmother the previous day","she'd visited her grandmother the day before"],"vi":"Reported speech — quá khứ đơn → quá khứ hoàn thành","explanation":"Quá khứ đơn trong câu trực tiếp lùi thêm một bậc về quá khứ hoàn thành (visited → had visited) khi tường thuật; trạng từ thời gian 'yesterday' phải đổi thành 'the day before' hoặc 'the previous day' vì không còn cùng ngày nói nữa. Đáp án: 'Hoa said that she had visited her grandmother the day before.'"},
  {"id":"rw-63","cat":"reported-statement","catLabel":"Câu tường thuật (câu kể)","orig":"\"I will meet you here tomorrow,\" Duc said to Lan.","stem":"Duc told Lan that","answer":"he would meet her there the next day","accept":["he would meet her there the next day","he would meet her there the next day.","he'd meet her there the next day","he would meet her there the following day"],"vi":"Reported speech — will → would (đổi trạng từ nơi chốn/thời gian)","explanation":"Khi có người nghe được nhắc tới (Duc said to Lan), động từ tường thuật đổi thành 'told + người nghe'; động từ khuyết thiếu 'will' lùi thành 'would'. Ngoài ra 'here' → 'there', 'tomorrow' → 'the next day'/'the following day', và 'you' → 'her' vì chỉ Lan. Đáp án: 'Duc told Lan that he would meet her there the next day.'"},
  {"id":"rw-64","cat":"reported-statement","catLabel":"Câu tường thuật (câu kể)","orig":"\"I was studying in this city last night,\" Trang said.","stem":"Trang said that","answer":"she had been studying in that city the night before","accept":["she had been studying in that city the night before","she had been studying in that city the night before.","she had been studying in that city the previous night","she'd been studying in that city the night before"],"vi":"Reported speech — quá khứ tiếp diễn → quá khứ hoàn thành tiếp diễn","explanation":"Thì quá khứ tiếp diễn trong câu trực tiếp lùi thành quá khứ hoàn thành tiếp diễn khi tường thuật (was studying → had been studying); tính từ chỉ định 'this' → 'that' và trạng từ 'last night' → 'the night before'/'the previous night'. Công thức: was/were + V-ing → had been + V-ing. Đáp án: 'Trang said that she had been studying in that city the night before.'"},
  {"id":"rw-65","cat":"reported-command","catLabel":"Câu tường thuật (mệnh lệnh/yêu cầu)","orig":"\"Please close the door quietly,\" the librarian said to us.","stem":"The librarian asked us","answer":"to close the door quietly","accept":["to close the door quietly","to close the door softly","to quietly close the door"],"vi":"ask sb to V — tường thuật yêu cầu lịch sự (Please + V)","explanation":"Câu yêu cầu lịch sự có \"Please\" + động từ nguyên mẫu được tường thuật bằng công thức: asked + tân ngữ + to + V (+ trạng từ cách thức nếu có). Áp dụng: \"Please close the door quietly\" → \"asked us to close the door quietly\", giữ nguyên trạng từ \"quietly\" chỉ cách thức. Đáp án đầy đủ: The librarian asked us to close the door quietly."},
  {"id":"rw-66","cat":"reported-command","catLabel":"Câu tường thuật (mệnh lệnh/yêu cầu)","orig":"\"Don't run in the hallway,\" the teacher said to the students.","stem":"The teacher told the students","answer":"not to run in the hallway","accept":["not to run in the hallway","to not run in the hallway"],"vi":"tell sb not to V — tường thuật mệnh lệnh phủ định","explanation":"Câu mệnh lệnh phủ định \"Don't + V\" (không có Please) khi tường thuật chuyển thành: told + tân ngữ + not to + V. Áp dụng: \"Don't run in the hallway\" → \"told the students not to run in the hallway\". Đáp án đầy đủ: The teacher told the students not to run in the hallway."},
  {"id":"rw-67","cat":"reported-command","catLabel":"Câu tường thuật (mệnh lệnh/yêu cầu)","orig":"\"Please water the plants every morning,\" Lan said to her sister.","stem":"Lan asked her sister","answer":"to water the plants every morning","accept":["to water the plants every morning","to water the plants each morning"],"vi":"ask sb to V — yêu cầu lịch sự có trạng từ tần suất","explanation":"Câu yêu cầu có \"Please\" giữ nguyên trạng ngữ chỉ tần suất khi chuyển sang lời tường thuật, dùng công thức asked + O + to + V. Áp dụng: \"Please water the plants every morning\" → \"asked her sister to water the plants every morning\". Đáp án đầy đủ: Lan asked her sister to water the plants every morning."},
  {"id":"rw-68","cat":"reported-command","catLabel":"Câu tường thuật (mệnh lệnh/yêu cầu)","orig":"\"Don't forget your umbrella,\" Mrs. Tran said to Minh.","stem":"Mrs. Tran told Minh","answer":"not to forget his umbrella","accept":["not to forget his umbrella","not to forget to bring his umbrella","not to forget to take his umbrella"],"vi":"tell sb not to V + đổi sở hữu — tường thuật mệnh lệnh phủ định","explanation":"Đại từ sở hữu \"your\" (chỉ người nghe trong câu trực tiếp) phải đổi thành đại từ phù hợp với người được nhắc tới trong câu tường thuật; vì Minh là nam nên \"your\" → \"his\". Cấu trúc: told + O + not to + V. Đáp án đầy đủ: Mrs. Tran told Minh not to forget his umbrella."},
  {"id":"rw-69","cat":"reported-command","catLabel":"Câu tường thuật (mệnh lệnh/yêu cầu)","orig":"\"Please wait for me outside the cinema,\" Nam said to Hoa.","stem":"Nam asked Hoa","answer":"to wait for him outside the cinema","accept":["to wait for him outside the cinema","to wait outside the cinema for him"],"vi":"ask sb to V + đổi đại từ tân ngữ — tường thuật yêu cầu","explanation":"Đại từ \"me\" trong câu trực tiếp chỉ người nói (Nam), nên khi tường thuật phải đổi thành \"him\". Cấu trúc: asked + O + to + V. Đáp án đầy đủ: Nam asked Hoa to wait for him outside the cinema."},
  {"id":"rw-70","cat":"reported-command","catLabel":"Câu tường thuật (mệnh lệnh/yêu cầu)","orig":"\"Don't use your phone during the exam,\" the invigilator said to the candidates.","stem":"The invigilator told the candidates","answer":"not to use their phones during the exam","accept":["not to use their phones during the exam","not to use their phone during the exam"],"vi":"tell sb not to V (đổi sở hữu số nhiều) — tường thuật mệnh lệnh phủ định","explanation":"Vì người nghe là \"the candidates\" (số nhiều), đại từ sở hữu \"your\" phải đổi thành \"their\"; mệnh lệnh phủ định dùng công thức told + O + not to + V. Đáp án đầy đủ: The invigilator told the candidates not to use their phones during the exam."},
  {"id":"rw-71","cat":"reported-command","catLabel":"Câu tường thuật (mệnh lệnh/yêu cầu)","orig":"\"Please don't make noise after 10 p.m.,\" the landlord said to the tenants.","stem":"The landlord asked the tenants","answer":"not to make noise after 10 p.m.","accept":["not to make noise after 10 p.m.","not to make noise after 10 pm","not to make noise after 10 p.m","not to make any noise after 10 pm"],"vi":"ask sb not to V — yêu cầu lịch sự phủ định (Please don't)","explanation":"\"Please don't + V\" là lời yêu cầu lịch sự ở dạng phủ định, được tường thuật bằng công thức: asked + O + not to + V (khác với told dùng cho mệnh lệnh không có Please). Đáp án đầy đủ: The landlord asked the tenants not to make noise after 10 p.m."},
  {"id":"rw-72","cat":"reported-command","catLabel":"Câu tường thuật (mệnh lệnh/yêu cầu)","orig":"\"Finish your homework before you watch TV tonight,\" Dad said to me.","stem":"Dad told me","answer":"to finish my homework before I watched TV that night","accept":["to finish my homework before i watched tv that night","to finish my homework before watching tv that night"],"vi":"tell sb to V + lùi thời gian/đại từ — tường thuật mệnh lệnh phức hợp","explanation":"Mệnh lệnh chính \"Finish your homework\" chuyển thành to + V (told + O + to + V); mệnh đề trạng ngữ thời gian đi kèm cũng lùi thì và đổi đại từ: \"your\"→\"my\", \"you watch\"→\"I watched\", \"tonight\"→\"that night\". Đáp án đầy đủ: Dad told me to finish my homework before I watched TV that night."},
  {"id":"rw-73","cat":"comparative-asas","catLabel":"So sánh hơn ↔ not as ... as","orig":"The new supermarket is bigger than the old market.","stem":"The old market is not","answer":"as big as the new supermarket","accept":["as big as the new supermarket","as big as the supermarket","as big as the new one"],"vi":"so sánh hơn (tính từ ngắn) → not as...as","explanation":"Công thức: S1 + tobe + adj-er + than + S2 → S2 + tobe + not as + adj (dạng gốc) + as + S1. Ở đây 'bigger' quay về dạng gốc 'big' khi ghép vào 'not as...as', nghĩa câu không đổi: chợ cũ không to bằng siêu thị mới. Đáp án đầy đủ: 'The old market is not as big as the new supermarket.'"},
  {"id":"rw-74","cat":"comparative-asas","catLabel":"So sánh hơn ↔ not as ... as","orig":"Mai's paintings are more colorful than Lan's paintings.","stem":"Lan's paintings are not","answer":"as colorful as Mai's","accept":["as colorful as mai's","as colorful as mais","as colorful as mai's paintings","as colorful as mais paintings"],"vi":"so sánh hơn (tính từ dài, more) → not as...as","explanation":"Với tính từ dài như 'colorful', câu so sánh hơn dùng 'more + adj'; khi chuyển sang 'not as...as' ta bỏ 'more' và giữ nguyên tính từ gốc: 'more colorful than' → 'not as colorful as'. Vế sau 'Mai's paintings' được rút gọn thành sở hữu cách 'Mai's' để tránh lặp danh từ 'paintings'. Đáp án đầy đủ: 'Lan's paintings are not as colorful as Mai's.'"},
  {"id":"rw-75","cat":"comparative-asas","catLabel":"So sánh hơn ↔ not as ... as","orig":"The express bus runs faster than the local bus.","stem":"The local bus does not run","answer":"as fast as the express bus","accept":["as fast as the express bus","as fast as the express bus does"],"vi":"so sánh hơn với trạng từ (fast) → not as...as","explanation":"Trạng từ ngắn 'fast' thêm '-er' để so sánh hơn giống tính từ ngắn; khi phủ định phải quay về dạng gốc 'fast' trong 'not as fast as'. Vì động từ chính 'run' là động từ thường, câu phủ định cần trợ động từ 'does not'. Đáp án đầy đủ: 'The local bus does not run as fast as the express bus.'"},
  {"id":"rw-76","cat":"comparative-asas","catLabel":"So sánh hơn ↔ not as ... as","orig":"Huy sings better than his younger brother.","stem":"Huy's younger brother does not sing","answer":"as well as Huy","accept":["as well as huy","as well as huy does"],"vi":"so sánh hơn bất quy tắc (well → better) → not as...as","explanation":"Trạng từ 'well' có dạng so sánh hơn bất quy tắc là 'better'; khi chuyển sang cấu trúc 'not as...as' phải quay về dạng gốc 'well', không được giữ 'better'. Đây là lỗi học sinh hay mắc vì nhầm với tính từ 'good'. Đáp án đầy đủ: 'Huy's younger brother does not sing as well as Huy.'"},
  {"id":"rw-77","cat":"comparative-asas","catLabel":"So sánh hơn ↔ not as ... as","orig":"Yesterday's Math test was more difficult than today's test.","stem":"Today's test was not","answer":"as difficult as yesterday's","accept":["as difficult as yesterday's","as difficult as yesterdays","as difficult as yesterday's test","as difficult as yesterdays test"],"vi":"so sánh hơn ở thì quá khứ → not as...as","explanation":"Ở thì quá khứ, động từ to be chia thành 'was/were' nhưng công thức chuyển đổi vẫn giữ nguyên: 'more difficult than' → 'not as difficult as'. Vế sau 'yesterday's test' được rút gọn thành sở hữu cách 'yesterday's' để tránh lặp danh từ 'test'. Đáp án đầy đủ: 'Today's test was not as difficult as yesterday's.'"},
  {"id":"rw-78","cat":"comparative-asas","catLabel":"So sánh hơn ↔ not as ... as","orig":"This mobile game is not as popular as that one.","stem":"That one is","answer":"more popular than this mobile game","accept":["more popular than this mobile game","more popular than this one","more popular than this game"],"vi":"not as...as → so sánh hơn (tính từ dài)","explanation":"Đây là chiều ngược lại: S1 + is not as + adj + as + S2 → S2 + is + more + adj + than + S1 (áp dụng với tính từ dài như 'popular'). Nghĩa giữ nguyên: trò chơi kia được ưa chuộng hơn trò chơi này. Đáp án đầy đủ: 'That one is more popular than this mobile game.'"},
  {"id":"rw-79","cat":"comparative-asas","catLabel":"So sánh hơn ↔ not as ... as","orig":"My grandmother is not as healthy as she was five years ago.","stem":"My grandmother was","answer":"healthier five years ago than she is now","accept":["healthier five years ago than she is now","healthier five years ago than she is today","healthier 5 years ago than she is now"],"vi":"not as...as (hiện tại/quá khứ) → so sánh hơn","explanation":"Chuyển từ 'not as...as' sang so sánh hơn: vế mang mức độ cao hơn trong nghĩa gốc (sức khỏe 5 năm trước) đứng trước động từ, vế còn lại (hiện tại) theo sau 'than'. Tính từ 'healthy' (tận cùng bằng 'y') đổi 'y' thành 'i' rồi thêm '-er' → 'healthier'. Đáp án đầy đủ: 'My grandmother was healthier five years ago than she is now.'"},
  {"id":"rw-80","cat":"comparative-asas","catLabel":"So sánh hơn ↔ not as ... as","orig":"Reducing plastic waste is not as effective as recycling in protecting the environment.","stem":"Recycling is","answer":"more effective than reducing plastic waste in protecting the environment","accept":["more effective than reducing plastic waste in protecting the environment","more effective than reducing plastic waste"],"vi":"not as...as → so sánh hơn (chủ ngữ V-ing)","explanation":"Chủ ngữ ở đây là danh động từ (V-ing): 'reducing plastic waste' và 'recycling', nhưng công thức chuyển đổi vẫn áp dụng bình thường vì 'effective' là tính từ dài: 'not as effective as' → 'more effective than'. Đáp án đầy đủ: 'Recycling is more effective than reducing plastic waste in protecting the environment.'"},
  {"id":"rw-81","cat":"superlative-never","catLabel":"So sánh nhất ↔ have never + hơn","orig":"This is the most delicious meal I have ever eaten.","stem":"I have never","answer":"eaten a more delicious meal","accept":["eaten a more delicious meal","eaten a more delicious meal before","eaten a more delicious meal than this","eaten a tastier meal","had a more delicious meal"],"vi":"So sánh nhất ↔ have never + so sánh hơn","explanation":"Công thức: 'the + so sánh nhất + N + (that) S have ever + V-ed/V3' chuyển thành 'S have never + V-ed/V3 + a/an + so sánh hơn + N (+ than...)'. Với tính từ dài như 'delicious' (3 âm tiết), so sánh hơn dùng 'more delicious', không thêm '-er'. Đáp án đầy đủ: I have never eaten a more delicious meal (than this)."},
  {"id":"rw-82","cat":"superlative-never","catLabel":"So sánh nhất ↔ have never + hơn","orig":"It is the funniest movie I have ever watched.","stem":"I have never","answer":"watched a funnier movie","accept":["watched a funnier movie","watched a funnier movie before","watched a funnier movie than this","seen a funnier movie"],"vi":"So sánh nhất ↔ have never + so sánh hơn","explanation":"'Funny' là tính từ 2 âm tiết tận cùng bằng phụ âm + 'y', nên khi so sánh hơn phải đổi 'y' thành 'i' rồi thêm '-er': funnier. Từ 'the funniest movie I have ever watched' ta suy ra 'I have never watched a funnier movie (than this)'."},
  {"id":"rw-83","cat":"superlative-never","catLabel":"So sánh nhất ↔ have never + hơn","orig":"Mr. Chen is the most patient teacher I have ever met.","stem":"I have never","answer":"met a more patient teacher","accept":["met a more patient teacher","met a more patient teacher before","met a more patient teacher than him","met a more patient teacher than mr chen"],"vi":"So sánh nhất ↔ have never + so sánh hơn","explanation":"Tính từ 2 âm tiết như 'patient' (không tận cùng bằng 'y', '-er', '-ow', '-le') dùng 'more' để so sánh hơn, không thêm đuôi '-er'. Từ 'the most patient teacher I have ever met' ta được 'I have never met a more patient teacher (than Mr. Chen)'."},
  {"id":"rw-84","cat":"superlative-never","catLabel":"So sánh nhất ↔ have never + hơn","orig":"That was the most difficult exam I have ever taken.","stem":"I have never","answer":"taken a more difficult exam","accept":["taken a more difficult exam","taken a more difficult exam before","taken a harder exam","taken a more difficult exam than that"],"vi":"So sánh nhất ↔ have never + so sánh hơn","explanation":"'Difficult' là tính từ dài (3 âm tiết) nên so sánh hơn là 'more difficult' (có thể thay bằng từ đồng nghĩa ngắn 'harder'). Mệnh đề chính dùng 'was' nhưng mệnh đề 'have ever taken' vẫn giữ thì hiện tại hoàn thành khi chuyển đổi: I have never taken a more difficult exam (than that)."},
  {"id":"rw-85","cat":"superlative-never","catLabel":"So sánh nhất ↔ have never + hơn","orig":"Hanoi is the most crowded city I have ever visited.","stem":"I have never","answer":"visited a more crowded city","accept":["visited a more crowded city","visited a more crowded city before","visited a more crowded city than hanoi","been to a more crowded city"],"vi":"So sánh nhất ↔ have never + so sánh hơn","explanation":"Tính từ có dạng phân từ '-ed' như 'crowded' luôn dùng 'more' để so sánh hơn, không thêm '-er'. Từ 'the most crowded city I have ever visited' ta được 'I have never visited a more crowded city (than Hanoi)'."},
  {"id":"rw-86","cat":"superlative-never","catLabel":"So sánh nhất ↔ have never + hơn","orig":"This is the saddest song I have ever heard.","stem":"I have never","answer":"heard a sadder song","accept":["heard a sadder song","heard a sadder song before","heard a sadder song than this"],"vi":"So sánh nhất ↔ have never + so sánh hơn","explanation":"'Sad' là tính từ ngắn 1 âm tiết dạng phụ âm-nguyên âm-phụ âm nên khi thêm '-er' phải gấp đôi phụ âm cuối: sadder. Câu 'the saddest song I have ever heard' chuyển thành 'I have never heard a sadder song (than this)'."},
  {"id":"rw-87","cat":"superlative-never","catLabel":"So sánh nhất ↔ have never + hơn","orig":"This is the best gift my parents have ever given me.","stem":"My parents have never","answer":"given me a better gift","accept":["given me a better gift","given me a better gift before","given a better gift to me","given me a better gift than this"],"vi":"So sánh nhất ↔ have never + so sánh hơn (tính từ bất quy tắc)","explanation":"'Good' là tính từ bất quy tắc, so sánh hơn là 'better' chứ không phải 'more good'. Chú ý chủ ngữ của mệnh đề quan hệ là 'my parents' (không phải 'I'), nên câu viết lại phải giữ đúng chủ ngữ này: My parents have never given me a better gift (than this)."},
  {"id":"rw-88","cat":"superlative-never","catLabel":"So sánh nhất ↔ have never + hơn","orig":"So far in my career, this is the most challenging project I have ever managed.","stem":"So far in my career, I have never","answer":"managed a more challenging project","accept":["managed a more challenging project","managed a more challenging project before","managed a more challenging project than this"],"vi":"So sánh nhất ↔ have never + so sánh hơn","explanation":"Cụm trạng ngữ 'so far in my career' được giữ nguyên ở đầu câu khi viết lại. Tính từ dài 'challenging' so sánh hơn bằng 'more challenging'. Từ 'the most challenging project I have ever managed' ta được phần còn thiếu: managed a more challenging project (than this one)."},
  {"id":"rw-89","cat":"used-to","catLabel":"Used to (thói quen quá khứ)","orig":"Tam rode his bicycle to school every morning last year, but this year his father drives him there.","stem":"Tam used","answer":"to ride his bicycle to school every morning last year","accept":["to ride his bicycle to school every morning last year","to ride his bicycle to school every morning","to ride his bike to school every morning last year","to ride his bike to school every morning"],"vi":"used to + V(nguyên mẫu) — thói quen quá khứ, nay đã thay đổi","explanation":"Công thức: S + used to + V(nguyên mẫu) diễn tả một hành động/thói quen lặp đi lặp lại trong quá khứ nhưng hiện tại không còn xảy ra nữa. Ở câu này, Tâm từng đạp xe đến trường mỗi sáng năm ngoái, còn năm nay thì bố chở đi, nên ta viết 'Tam used to ride his bicycle to school every morning last year'. Đáp án đầy đủ: to ride his bicycle to school every morning last year."},
  {"id":"rw-90","cat":"used-to","catLabel":"Used to (thói quen quá khứ)","orig":"Mai didn't drink coffee when she was in grade 6, but she drinks a cup every morning now.","stem":"Mai didn't","answer":"use to drink coffee when she was in grade 6","accept":["use to drink coffee when she was in grade 6","use to drink coffee in grade 6"],"vi":"didn't use to + V — phủ định thói quen quá khứ","explanation":"Ở thể phủ định, cấu trúc chuẩn là S + didn't + use to + V (không chia 'used' vì trợ động từ 'did' đã mang thì quá khứ, đây là lỗi rất hay gặp nên cần lưu ý). Câu gốc cho biết Mai trước đây không uống cà phê nhưng bây giờ thì có, nên viết lại: 'Mai didn't use to drink coffee when she was in grade 6'. Đáp án: use to drink coffee when she was in grade 6."},
  {"id":"rw-91","cat":"used-to","catLabel":"Used to (thói quen quá khứ)","orig":"Phong was afraid of dogs when he was a small boy, but he isn't afraid of them anymore.","stem":"Phong used","answer":"to be afraid of dogs when he was a small boy","accept":["to be afraid of dogs when he was a small boy","to be afraid of dogs as a small boy","to be scared of dogs when he was a small boy","to be afraid of dogs when he was small"],"vi":"used to + be + tính từ — trạng thái/cảm xúc quá khứ","explanation":"'Used to' không chỉ đi với động từ hành động mà còn kết hợp với 'be + tính từ' để nói về một trạng thái hay cảm xúc từng đúng trong quá khứ nhưng nay đã khác. Phong từng sợ chó hồi nhỏ nhưng giờ đã hết sợ, nên ta viết 'Phong used to be afraid of dogs...'. Đáp án: to be afraid of dogs when he was a small boy."},
  {"id":"rw-92","cat":"used-to","catLabel":"Used to (thói quen quá khứ)","orig":"Duc read comic books every night before bed, but he no longer does that.","stem":"Duc used","answer":"to read comic books every night before bed","accept":["to read comic books every night before bed","to read comic books every night before going to bed","to read comic books before bed every night"],"vi":"no longer → used to + V — dấu hiệu thói quen đã chấm dứt","explanation":"Cụm 'no longer' (không còn nữa) là tín hiệu rõ ràng để chuyển câu sang cấu trúc 'used to' khi thói quen đó đã hoàn toàn chấm dứt ở hiện tại. Đức từng đọc truyện tranh mỗi tối trước khi ngủ nhưng giờ không còn làm vậy, nên viết 'Duc used to read comic books every night before bed'. Đáp án: to read comic books every night before bed."},
  {"id":"rw-93","cat":"used-to","catLabel":"Used to (thói quen quá khứ)","orig":"Hoa and her father played badminton together every weekend, but they don't have time for that now.","stem":"Hoa and her father used","answer":"to play badminton together every weekend","accept":["to play badminton together every weekend","to play badminton every weekend","to play badminton together on weekends"],"vi":"used to + V — thói quen chung của chủ ngữ số nhiều/ghép","explanation":"'Used to' không chia theo ngôi hay số của chủ ngữ, nên áp dụng được cho cả chủ ngữ ghép như 'Hoa and her father'. Hai bố con từng chơi cầu lông cùng nhau mỗi cuối tuần nhưng nay không còn thời gian, nên viết 'Hoa and her father used to play badminton together every weekend'. Đáp án: to play badminton together every weekend."},
  {"id":"rw-94","cat":"used-to","catLabel":"Used to (thói quen quá khứ)","orig":"Years ago, Khoa stayed up until midnight playing games, but he goes to bed early now.","stem":"Khoa used","answer":"to stay up until midnight playing games years ago","accept":["to stay up until midnight playing games years ago","to stay up until midnight playing games","to stay up late playing games years ago"],"vi":"used to + V — thói quen quá khứ xa, đối lập rõ với hiện tại","explanation":"Khi câu gốc có mốc thời gian quá khứ rõ ràng như 'years ago' đối lập với thói quen hiện tại ('goes to bed early now'), 'used to' giúp nhấn mạnh sự thay đổi hoàn toàn về thói quen; trạng ngữ 'years ago' có thể chuyển ra cuối câu. Khoa từng thức đến nửa đêm chơi game nhiều năm trước nhưng giờ đi ngủ sớm, nên viết 'Khoa used to stay up until midnight playing games years ago'. Đáp án: to stay up until midnight playing games years ago."},
  {"id":"rw-95","cat":"used-to","catLabel":"Used to (thói quen quá khứ)","orig":"When Lan was a student, she got up at five and jogged around the park every morning, but she doesn't do either now.","stem":"Lan used","answer":"to get up at five and jog around the park every morning when she was a student","accept":["to get up at five and jog around the park every morning when she was a student","to get up at five and jog around the park every morning","to get up at 5 and jog around the park every morning when she was a student"],"vi":"used to + V1 and V2 — hai thói quen song song trong quá khứ","explanation":"Khi câu có hai hành động thói quen nối với nhau bằng 'and', ta chỉ cần 'to' một lần trước động từ đầu, động từ thứ hai giữ nguyên dạng gốc: 'used to get up ... and jog ...'. Lan từng dậy sớm và chạy bộ mỗi sáng khi còn là học sinh nhưng bây giờ không làm cả hai việc đó nữa. Đáp án: to get up at five and jog around the park every morning when she was a student."},
  {"id":"rw-96","cat":"used-to","catLabel":"Used to (thói quen quá khứ)","orig":"Binh never ate breakfast before going to school when he was young, but he always has a full breakfast now.","stem":"Binh didn't","answer":"use to eat breakfast before going to school when he was young","accept":["use to eat breakfast before going to school when he was young","use to eat breakfast before school when he was young"],"vi":"never + V(quá khứ) → didn't use to + V — thói quen phủ định tuyệt đối","explanation":"Ở thể phủ định, ta dùng S + didn't + use to + V (không chia 'used' vì 'did' đã mang thì quá khứ). Cụm 'never + V-ed' trong câu gốc diễn tả một thói quen phủ định tuyệt đối trong quá khứ, khi chuyển sang 'used to' ta viết 'didn't use to + V' để giữ nguyên nghĩa 'trước đây không bao giờ làm gì, nhưng giờ thì có'. Bình trước đây không bao giờ ăn sáng trước khi đến trường nhưng bây giờ luôn ăn sáng đầy đủ, nên viết 'Binh didn't use to eat breakfast before going to school when he was young'. Đáp án: use to eat breakfast before going to school when he was young."},
  {"id":"rw-97","cat":"mind-ving","catLabel":"Don't mind / enjoy + V-ing","orig":"It doesn't matter to Lan if she has to walk to school every morning.","stem":"Lan doesn't mind","answer":"walking to school every morning","accept":["walking to school every morning","walking to school each morning","walking to school"],"vi":"don't mind + V-ing — không phiền khi làm gì","explanation":"Cấu trúc 'It doesn't matter to sb if sb has to V' (dù phải làm gì thì điều đó cũng không quan trọng/không phiền với ai) được viết lại thành 'S + doesn't/don't mind + V-ing'. Chủ ngữ số ít 'Lan' đi với 'doesn't mind', động từ 'walk' thêm '-ing' thành 'walking'. Đáp án đầy đủ: Lan doesn't mind walking to school every morning."},
  {"id":"rw-98","cat":"mind-ving","catLabel":"Don't mind / enjoy + V-ing","orig":"Minh likes reading comic books in his free time very much.","stem":"Minh enjoys","answer":"reading comic books in his free time","accept":["reading comic books in his free time","reading comic books in his spare time","reading comic books"],"vi":"enjoy + V-ing — thích thú khi làm gì","explanation":"Cấu trúc 'S + like/love + V-ing + very much' được rút gọn thành 'S + enjoy(s) + V-ing', bỏ 'very much' vì bản thân 'enjoy' đã mang nghĩa rất thích. 'Minh' là ngôi thứ ba số ít nên dùng 'enjoys'. Đáp án đầy đủ: Minh enjoys reading comic books in his free time."},
  {"id":"rw-99","cat":"mind-ving","catLabel":"Don't mind / enjoy + V-ing","orig":"It doesn't matter to my sister if she has to share her room with our cousin.","stem":"My sister doesn't mind","answer":"sharing her room with our cousin","accept":["sharing her room with our cousin","sharing the room with our cousin","sharing her room with my cousin"],"vi":"don't mind + V-ing — không phiền khi làm gì","explanation":"Áp dụng công thức 'It doesn't matter to sb if sb has to V' → 'sb + doesn't/don't mind + V-ing'. Chủ ngữ số ít 'my sister' đi với 'doesn't mind', động từ 'share' thêm '-ing' thành 'sharing'. Đáp án đầy đủ: My sister doesn't mind sharing her room with our cousin."},
  {"id":"rw-100","cat":"mind-ving","catLabel":"Don't mind / enjoy + V-ing","orig":"Duc likes playing badminton with his classmates after school very much.","stem":"Duc enjoys","answer":"playing badminton with his classmates after school","accept":["playing badminton with his classmates after school","playing badminton with his classmates","playing badminton with his friends after school"],"vi":"enjoy + V-ing — thích thú khi làm gì","explanation":"'S + like + V-ing + very much' chuyển thành 'S + enjoy(s) + V-ing'. Vì 'Duc' là số ít nên dùng 'enjoys', cụm trạng ngữ 'with his classmates after school' giữ nguyên ở cuối câu. Đáp án đầy đủ: Duc enjoys playing badminton with his classmates after school."},
  {"id":"rw-101","cat":"mind-ving","catLabel":"Don't mind / enjoy + V-ing","orig":"It doesn't matter to Mai if she has to stay up late to finish her project.","stem":"Mai doesn't mind","answer":"staying up late to finish her project","accept":["staying up late to finish her project","staying up late to finish the project","staying up late in order to finish her project"],"vi":"don't mind + V-ing — không phiền khi làm gì","explanation":"Với cấu trúc 'It doesn't matter to sb if sb has to V' → 'sb + doesn't mind + V-ing', động từ 'stay' thêm '-ing' thành 'staying'; mệnh đề mục đích 'to finish her project' giữ nguyên vì nó chỉ bổ nghĩa cho hành động chính, không phải động từ cần chuyển. Đáp án đầy đủ: Mai doesn't mind staying up late to finish her project."},
  {"id":"rw-102","cat":"mind-ving","catLabel":"Don't mind / enjoy + V-ing","orig":"Our teacher likes explaining difficult grammar points to us very much.","stem":"Our teacher enjoys","answer":"explaining difficult grammar points to us","accept":["explaining difficult grammar points to us","explaining difficult grammar points","explaining hard grammar points to us"],"vi":"enjoy + V-ing — thích thú khi làm gì","explanation":"Cấu trúc 'S + like + V-ing + very much' được rút gọn thành 'S + enjoy(s) + V-ing'. Chủ ngữ 'our teacher' là số ít nên dùng 'enjoys', động từ 'explain' thêm '-ing'. Đáp án đầy đủ: Our teacher enjoys explaining difficult grammar points to us."},
  {"id":"rw-103","cat":"mind-ving","catLabel":"Don't mind / enjoy + V-ing","orig":"It doesn't matter to the twins, who are in grade 9, if they have to help their mother cook dinner every evening.","stem":"The twins, who are in grade 9, don't mind","answer":"helping their mother cook dinner every evening","accept":["helping their mother cook dinner every evening","helping their mother to cook dinner every evening","helping their mother cook dinner"],"vi":"don't mind + V-ing (có mệnh đề quan hệ) — không phiền khi làm gì","explanation":"Mệnh đề quan hệ không xác định 'who are in grade 9' chỉ bổ sung thông tin nên được giữ nguyên trong câu viết lại; phần chính 'it doesn't matter to sb if sb has to V' chuyển thành 'sb + don't mind + V-ing'. Vì 'the twins' số nhiều nên dùng 'don't mind', và 'help' có thể theo sau bởi V-ing hoặc to-V. Đáp án đầy đủ: The twins, who are in grade 9, don't mind helping their mother cook dinner every evening."},
  {"id":"rw-104","cat":"mind-ving","catLabel":"Don't mind / enjoy + V-ing","orig":"Even though he is very busy with exams, it doesn't matter to Phong if he has to look after his younger brother after school.","stem":"Even though he is very busy with exams, Phong doesn't mind","answer":"looking after his younger brother after school","accept":["looking after his younger brother after school","looking after his little brother after school","taking care of his younger brother after school"],"vi":"don't mind + V-ing (có mệnh đề nhượng bộ) — không phiền khi làm gì","explanation":"Mệnh đề nhượng bộ 'Even though...' được giữ nguyên ở đầu câu, còn phần 'it doesn't matter to sb if sb has to V' chuyển thành 'sb + doesn't mind + V-ing'. Cụm động từ 'look after' (chăm sóc) thêm '-ing' thành 'looking after', trạng ngữ 'after school' giữ nguyên ở cuối. Đáp án đầy đủ: Even though he is very busy with exams, Phong doesn't mind looking after his younger brother after school."},
  {"id":"rw-105","cat":"since-lasttime","catLabel":"Present perfect ↔ The last time / It has been ... since","orig":"My brother hasn't visited our grandparents in the countryside for six months.","stem":"It has been","answer":"six months since my brother last visited our grandparents in the countryside","accept":["six months since my brother last visited our grandparents in the countryside","6 months since my brother last visited our grandparents in the countryside","six months since my brother last visited our grandparents","6 months since my brother last visited our grandparents"],"vi":"hasn't + PII + for + thời gian → It has been + thời gian + since + S + last + QKĐ","explanation":"Công thức: S + haven't/hasn't + V3/ed + for + khoảng thời gian = It has been + khoảng thời gian + since + S + last + V (quá khứ đơn). Câu gốc có 'for six months' nên khoảng thời gian là 'six months', động từ 'visited' giữ nguyên ở quá khứ đơn sau 'last'. Đáp án đầy đủ: It has been six months since my brother last visited our grandparents in the countryside."},
  {"id":"rw-106","cat":"since-lasttime","catLabel":"Present perfect ↔ The last time / It has been ... since","orig":"It has been three years since our class last had a field trip to Da Lat.","stem":"Our class","answer":"hasn't had a field trip to Da Lat for three years","accept":["hasn't had a field trip to da lat for three years","has not had a field trip to da lat for three years","hasn't had a field trip to da lat in three years","has not had a field trip to da lat in three years"],"vi":"It has been + thời gian + since + S + last + QKĐ → S + haven't/hasn't + PII + for + thời gian","explanation":"Công thức ngược lại: It has been + khoảng thời gian + since + S + last + V (QKĐ) = S + haven't/hasn't + V3/ed + for + khoảng thời gian. Câu gốc có 'three years' và động từ 'had' (QKĐ của have), nên ta chuyển thành hiện tại hoàn thành phủ định 'hasn't had'. Đáp án đầy đủ: Our class hasn't had a field trip to Da Lat for three years."},
  {"id":"rw-107","cat":"since-lasttime","catLabel":"Present perfect ↔ The last time / It has been ... since","orig":"My mother hasn't cooked a big family dinner for over a month.","stem":"The last time my mother cooked a big family dinner was","answer":"over a month ago","accept":["over a month ago","more than a month ago","over one month ago"],"vi":"hasn't + PII + for + thời gian → The last time + S + QKĐ + was + thời gian + ago","explanation":"Công thức: S + haven't/hasn't + V3/ed + for + khoảng thời gian = The last time + S + V (QKĐ) + was + khoảng thời gian + ago. Câu gốc có 'for over a month' và động từ 'cooked' đã ở QKĐ, ta chỉ cần thêm 'was' và đổi 'for' thành 'ago'. Đáp án đầy đủ: The last time my mother cooked a big family dinner was over a month ago."},
  {"id":"rw-108","cat":"since-lasttime","catLabel":"Present perfect ↔ The last time / It has been ... since","orig":"The last time Nam repaired his old bicycle was five years ago.","stem":"Nam","answer":"hasn't repaired his old bicycle for five years","accept":["hasn't repaired his old bicycle for five years","has not repaired his old bicycle for five years","hasn't repaired his old bicycle in five years","has not repaired his old bicycle in five years"],"vi":"The last time + S + QKĐ + was + thời gian + ago → S + haven't/hasn't + PII + for + thời gian","explanation":"Công thức ngược: The last time + S + V (QKĐ) + was + khoảng thời gian + ago = S + haven't/hasn't + V3/ed + for + khoảng thời gian. Câu gốc có 'five years ago' và động từ 'repaired' (động từ có quy tắc, PII giữ nguyên dạng 'repaired'), ta thêm 'hasn't' và đổi 'ago' thành 'for'. Đáp án đầy đủ: Nam hasn't repaired his old bicycle for five years."},
  {"id":"rw-109","cat":"since-lasttime","catLabel":"Present perfect ↔ The last time / It has been ... since","orig":"The volunteers haven't cleaned up the local beach for nearly a year.","stem":"It has been","answer":"nearly a year since the volunteers last cleaned up the local beach","accept":["nearly a year since the volunteers last cleaned up the local beach","almost a year since the volunteers last cleaned up the local beach","nearly a year since the volunteers last cleaned the local beach up"],"vi":"haven't + PII + for + thời gian → It has been + thời gian + since + S + last + QKĐ","explanation":"Áp dụng công thức: S + haven't/hasn't + V3/ed + for + khoảng thời gian = It has been + khoảng thời gian + since + S + last + V (QKĐ). Câu gốc có 'for nearly a year' và cụm động từ 'cleaned up', ta giữ nguyên phrasal verb này ở quá khứ đơn sau 'last'. Đáp án đầy đủ: It has been nearly a year since the volunteers last cleaned up the local beach."},
  {"id":"rw-110","cat":"since-lasttime","catLabel":"Present perfect ↔ The last time / It has been ... since","orig":"This factory hasn't updated its safety equipment for four years.","stem":"The last time this factory updated its safety equipment was","answer":"four years ago","accept":["four years ago","4 years ago"],"vi":"hasn't + PII + for + thời gian → The last time + S + QKĐ + was + thời gian + ago","explanation":"Công thức: S + haven't/hasn't + V3/ed + for + khoảng thời gian = The last time + S + V (QKĐ) + was + khoảng thời gian + ago. Câu gốc có 'for four years' và động từ 'updated', ta chuyển 'for' thành 'ago' và thêm 'was' phía trước. Đáp án đầy đủ: The last time this factory updated its safety equipment was four years ago."},
  {"id":"rw-111","cat":"since-lasttime","catLabel":"Present perfect ↔ The last time / It has been ... since","orig":"It has been eight months since the two neighboring countries last held trade talks.","stem":"The two neighboring countries","answer":"haven't held trade talks for eight months","accept":["haven't held trade talks for eight months","have not held trade talks for eight months","haven't held trade talks in eight months","have not held trade talks in eight months"],"vi":"It has been + thời gian + since + S + last + QKĐ → S + haven't/hasn't + PII + for + thời gian","explanation":"Công thức: It has been + khoảng thời gian + since + S + last + V (QKĐ) = S + haven't/hasn't + V3/ed + for + khoảng thời gian. Câu gốc có 'eight months' và động từ 'held' (QKĐ và PII của 'hold' đều là 'held'), nên hiện tại hoàn thành phủ định là 'haven't held'. Đáp án đầy đủ: The two neighboring countries haven't held trade talks for eight months."},
  {"id":"rw-112","cat":"since-lasttime","catLabel":"Present perfect ↔ The last time / It has been ... since","orig":"The last time the research team published a new study was over three years ago.","stem":"The research team","answer":"hasn't published a new study for over three years","accept":["hasn't published a new study for over three years","has not published a new study for over three years","hasn't published a new study in over three years","has not published a new study in over three years"],"vi":"The last time + S + QKĐ + was + thời gian + ago → S + haven't/hasn't + PII + for + thời gian","explanation":"Công thức: The last time + S + V (QKĐ) + was + khoảng thời gian + ago = S + haven't/hasn't + V3/ed + for + khoảng thời gian. Câu gốc có 'over three years ago' và động từ 'published' (động từ có quy tắc), ta thêm 'hasn't' và đổi 'ago' thành 'for', giữ nguyên 'over' để không làm sai lệch khoảng thời gian. Đáp án đầy đủ: The research team hasn't published a new study for over three years."},
  {"id":"rw-113","cat":"howlong-ago","catLabel":"started ... ago ↔ have + for / How long","orig":"Nam started learning to play the piano three years ago.","stem":"Nam has","answer":"learned to play the piano for three years","accept":["learned to play the piano for three years","learned to play the piano for 3 years","learnt to play the piano for three years","learned how to play the piano for three years"],"vi":"started + V-ing + ago → have/has + V-ed + for — mốc thời gian quá khứ chuyển thành khoảng thời gian kéo dài","explanation":"Công thức: S + started + V-ing + khoảng thời gian + ago = S + have/has + V-ed/V3 + for + khoảng thời gian, dùng khi hành động bắt đầu trong quá khứ và vẫn kéo dài đến hiện tại. Ở câu này, 'three years ago' chuyển thành 'for three years', động từ 'learn' chia ở dạng quá khứ phân từ 'learned' (Anh-Anh: 'learnt'). Đáp án đầy đủ: Nam has learned to play the piano for three years."},
  {"id":"rw-114","cat":"howlong-ago","catLabel":"started ... ago ↔ have + for / How long","orig":"My sister started working at this bakery two years ago.","stem":"My sister has","answer":"worked at this bakery for two years","accept":["worked at this bakery for two years","worked at this bakery for 2 years","worked in this bakery for two years"],"vi":"started + V-ing + ago → have/has + V-ed + for — hành động bắt đầu trong quá khứ, vẫn tiếp diễn đến nay","explanation":"Khi một hành động bắt đầu ở một mốc trong quá khứ ('two years ago') và còn tiếp tục đến bây giờ, ta chuyển sang thì hiện tại hoàn thành và thay 'ago' bằng 'for + khoảng thời gian'. Chủ ngữ số ít 'my sister' nên dùng trợ động từ 'has'. Đáp án: My sister has worked at this bakery for two years."},
  {"id":"rw-115","cat":"howlong-ago","catLabel":"started ... ago ↔ have + for / How long","orig":"Huy and Mai started dating one year ago.","stem":"Huy and Mai have","answer":"dated for one year","accept":["dated for one year","dated for 1 year","dated for a year"],"vi":"started + V-ing + ago → have + V-ed + for — chủ ngữ số nhiều dùng 'have'","explanation":"Với chủ ngữ số nhiều (Huy and Mai), trợ động từ 'to have' chia là 'have', không phải 'has'. Mốc thời gian 'one year ago' chuyển thành 'for one year' để nhấn mạnh mối quan hệ vẫn đang tiếp diễn; vì chủ ngữ đã nêu rõ hai người nên không cần lặp lại 'each other'. Đáp án: Huy and Mai have dated for one year."},
  {"id":"rw-116","cat":"howlong-ago","catLabel":"started ... ago ↔ have + for / How long","orig":"Our neighbors started keeping bees five years ago.","stem":"Our neighbors have","answer":"kept bees for five years","accept":["kept bees for five years","kept bees for 5 years","kept some bees for five years"],"vi":"started + V-ing + ago → have/has + V3 + for — động từ bất quy tắc (keep – kept – kept)","explanation":"'Keep' là động từ bất quy tắc, quá khứ phân từ là 'kept'. Cấu trúc chuyển đổi giữ nguyên: bỏ 'started' và 'ago', thêm 'have/has + V3' và 'for + khoảng thời gian'. Đáp án: Our neighbors have kept bees for five years."},
  {"id":"rw-117","cat":"howlong-ago","catLabel":"started ... ago ↔ have + for / How long","orig":"Tam became a member of the school chess club nine months ago.","stem":"Tam has","answer":"been a member of the school chess club for nine months","accept":["been a member of the school chess club for nine months","been a member of the school chess club for 9 months","been a member of the chess club for nine months"],"vi":"became + danh từ + ago → have/has been + danh từ + for — 'became' tương đương 'started being'","explanation":"Khi một người 'became' (trở thành) một vai trò/tư cách nào đó tại một mốc trong quá khứ và vẫn giữ vai trò ấy đến hiện tại, ta dùng have/has been + danh từ + for + khoảng thời gian (vì 'became' tương đương 'started being', và quá khứ phân từ của 'be' là 'been'). Chủ ngữ 'Tam' số ít nên dùng 'has'. Đáp án: Tam has been a member of the school chess club for nine months."},
  {"id":"rw-118","cat":"howlong-ago","catLabel":"started ... ago ↔ have + for / How long","orig":"Mr. Long started teaching English at that language center seven years ago.","stem":"Mr. Long has","answer":"taught English at that language center for seven years","accept":["taught english at that language center for seven years","taught english at that language center for 7 years","taught english at that language centre for seven years"],"vi":"started + V-ing + ago → have/has + V3 + for — động từ bất quy tắc (teach – taught – taught)","explanation":"'Teach' có quá khứ phân từ bất quy tắc là 'taught'. Khi câu có nhiều thành phần (tân ngữ 'English' và trạng ngữ nơi chốn 'at that language center'), ta giữ nguyên các thành phần đó và chỉ đổi phần thời gian 'seven years ago' thành 'for seven years', đồng thời đổi động từ sang have/has + V3. Đáp án: Mr. Long has taught English at that language center for seven years."},
  {"id":"rw-119","cat":"howlong-ago","catLabel":"started ... ago ↔ have + for / How long","orig":"She started growing organic vegetables in her backyard eight years ago.","stem":"She has","answer":"grown organic vegetables in her backyard for eight years","accept":["grown organic vegetables in her backyard for eight years","grown organic vegetables in her backyard for 8 years","grown organic vegetables in the backyard for eight years"],"vi":"started + V-ing + ago → have/has + V3 + for — động từ bất quy tắc (grow – grew – grown)","explanation":"Động từ 'grow' bất quy tắc: grow – grew – grown. Cụm tính từ + danh từ ('organic vegetables') và trạng ngữ nơi chốn ('in her backyard') được giữ nguyên vị trí, chỉ đổi phần đầu (started... ago) thành have/has + V3... for. Đáp án: She has grown organic vegetables in her backyard for eight years."},
  {"id":"rw-120","cat":"howlong-ago","catLabel":"started ... ago ↔ have + for / How long","orig":"They started running the local youth football club in their neighborhood eleven years ago.","stem":"They have","answer":"run the local youth football club in their neighborhood for eleven years","accept":["run the local youth football club in their neighborhood for eleven years","run the local youth football club in their neighborhood for 11 years","run the local youth football club in the neighborhood for eleven years","run the local youth football club in their neighbourhood for eleven years"],"vi":"started + V-ing + ago → have + V3 + for — động từ đặc biệt (run – ran – run), câu dài nhiều cụm bổ nghĩa","explanation":"'Run' là động từ bất quy tắc đặc biệt vì quá khứ phân từ trùng với nguyên mẫu: run – ran – run. Với câu dài có nhiều cụm bổ nghĩa (tân ngữ 'the local youth football club' và trạng ngữ nơi chốn 'in their neighborhood'), ta chỉ cần thay 'started running... eleven years ago' bằng 'have run... for eleven years', các cụm còn lại giữ nguyên vị trí. Đáp án: They have run the local youth football club in their neighborhood for eleven years."},
  {"id":"rw-121","cat":"phrasal","catLabel":"Phrasal verbs (run out of, break down, put off, look after...)","orig":"There is no more sugar left in the jar.","stem":"The jar has run","answer":"out of sugar","accept":["out of sugar","out of sugar."],"vi":"run out of + N — hết sạch, không còn gì","explanation":"Công thức: S + run out of + N = (vật/nơi chứa) hết sạch cái gì; cấu trúc tương tự \"the car ran out of gas\". Câu gốc \"There is no more sugar left in the jar\" cho biết cái lọ đã hết đường ở hiện tại nên ta dùng thì hiện tại hoàn thành \"has run out of\" và đổi chủ ngữ thành \"the jar\". Đáp án đầy đủ: The jar has run out of sugar."},
  {"id":"rw-122","cat":"phrasal","catLabel":"Phrasal verbs (run out of, break down, put off, look after...)","orig":"My father's car suddenly stopped working on the highway yesterday.","stem":"My father's car suddenly broke","answer":"down on the highway yesterday","accept":["down on the highway yesterday","down on the highway yesterday."],"vi":"break down — (xe, máy) hỏng, chết máy","explanation":"Công thức: S + break down = xe cộ/máy móc đột ngột hỏng, ngừng hoạt động, đồng nghĩa \"stop working\". Câu gốc giữ nguyên vị trí trạng từ \"suddenly\" trước động từ, chỉ thay \"stopped working\" bằng phrasal verb \"broke down\", các trạng ngữ nơi chốn và thời gian đứng sau không đổi. Đáp án đầy đủ: My father's car suddenly broke down on the highway yesterday."},
  {"id":"rw-123","cat":"phrasal","catLabel":"Phrasal verbs (run out of, break down, put off, look after...)","orig":"The manager decided to postpone the meeting until next Monday.","stem":"The manager decided to put","answer":"off the meeting until next Monday","accept":["off the meeting until next monday","off the meeting until next monday.","the meeting off until next monday"],"vi":"put off + N (put + N + off) — hoãn lại","explanation":"Công thức: put off + N hoặc put + N + off = hoãn việc gì lại, đồng nghĩa \"postpone\"; đây là phrasal verb tách được (separable) nên tân ngữ có thể đứng giữa hoặc sau. Câu gốc \"postpone the meeting until next Monday\" được viết lại bằng \"put off the meeting until next Monday\". Đáp án đầy đủ: The manager decided to put off the meeting until next Monday."},
  {"id":"rw-124","cat":"phrasal","catLabel":"Phrasal verbs (run out of, break down, put off, look after...)","orig":"My grandmother takes care of my little brother while my parents are at work.","stem":"My grandmother looks","answer":"after my little brother while my parents are at work","accept":["after my little brother while my parents are at work","after my little brother while my parents are at work.","after my little brother, while my parents are at work"],"vi":"look after + N — chăm sóc, trông nom","explanation":"Công thức: look after + N = chăm sóc, trông nom ai/cái gì, đồng nghĩa \"take care of\". Câu gốc dùng \"takes care of my little brother\", ta thay bằng \"looks after my little brother\" và giữ nguyên mệnh đề thời gian \"while my parents are at work\". Đáp án đầy đủ: My grandmother looks after my little brother while my parents are at work."},
  {"id":"rw-125","cat":"phrasal","catLabel":"Phrasal verbs (run out of, break down, put off, look after...)","orig":"Tom stopped smoking last year because of his health problems.","stem":"Tom gave","answer":"up smoking last year because of his health problems","accept":["up smoking last year because of his health problems","up smoking last year because of his health problems."],"vi":"give up + V-ing — từ bỏ, ngừng làm gì","explanation":"Công thức: give up + V-ing = từ bỏ hẳn một thói quen, đồng nghĩa \"stop + V-ing\". Câu gốc \"stopped smoking\" được viết lại thành \"gave up smoking\", các trạng ngữ thời gian và lý do phía sau giữ nguyên. Đáp án đầy đủ: Tom gave up smoking last year because of his health problems."},
  {"id":"rw-126","cat":"phrasal","catLabel":"Phrasal verbs (run out of, break down, put off, look after...)","orig":"She rejected the job offer because the salary was too low.","stem":"She turned","answer":"down the job offer because the salary was too low","accept":["down the job offer because the salary was too low","down the job offer because the salary was too low.","the job offer down because the salary was too low"],"vi":"turn down + N (turn + N + down) — từ chối","explanation":"Công thức: turn down + N hoặc turn + N + down = từ chối một lời đề nghị/cơ hội, đồng nghĩa \"reject/refuse\"; đây cũng là phrasal verb tách được. Câu gốc \"rejected the job offer\" được thay bằng \"turned down the job offer\", mệnh đề lý do phía sau giữ nguyên. Đáp án đầy đủ: She turned down the job offer because the salary was too low."},
  {"id":"rw-127","cat":"phrasal","catLabel":"Phrasal verbs (run out of, break down, put off, look after...)","orig":"We are very excited about visiting our cousins next summer.","stem":"We are looking","answer":"forward to visiting our cousins next summer","accept":["forward to visiting our cousins next summer","forward to visiting our cousins next summer."],"vi":"look forward to + V-ing — mong chờ, háo hức","explanation":"Công thức: look forward to + V-ing/N = mong chờ, háo hức điều gì; lưu ý \"to\" ở đây là giới từ nên động từ theo sau phải chia V-ing, không phải nguyên mẫu. Câu gốc \"are very excited about visiting\" được viết lại bằng \"are looking forward to visiting\". Đáp án đầy đủ: We are looking forward to visiting our cousins next summer."},
  {"id":"rw-128","cat":"phrasal","catLabel":"Phrasal verbs (run out of, break down, put off, look after...)","orig":"I can no longer tolerate my neighbor's loud music every night.","stem":"I can no longer put","answer":"up with my neighbor's loud music every night","accept":["up with my neighbor's loud music every night","up with my neighbor's loud music every night.","up with my neighbors loud music every night","up with my neighbour's loud music every night"],"vi":"put up with + N/V-ing — chịu đựng","explanation":"Công thức: put up with + N/V-ing = chịu đựng một điều khó chịu, đồng nghĩa \"tolerate/bear\"; đây là phrasal verb ba thành phần, không tách được. Câu gốc \"can no longer tolerate my neighbor's loud music every night\" được viết lại bằng \"can no longer put up with my neighbor's loud music every night\". Đáp án đầy đủ: I can no longer put up with my neighbor's loud music every night."},
  {"id":"rw-129","cat":"imperative-or","catLabel":"Mệnh lệnh + or ↔ If ... not / Unless","orig":"Charge your phone tonight, or it will die during the trip tomorrow.","stem":"If you don't","answer":"charge your phone tonight, it will die during the trip tomorrow","accept":["charge your phone tonight, it will die during the trip tomorrow","charge your phone tonight it will die during the trip tomorrow","charge your phone tonight, it'll die during the trip tomorrow","charge your phone tonight it'll die during the trip tomorrow"],"vi":"Mệnh lệnh + or → If ... don't/doesn't — điều kiện phủ định ở hiện tại","explanation":"Công thức: [Mệnh lệnh], or + mệnh đề tương lai = If + S + don't/doesn't + V (nguyên mẫu của mệnh lệnh), mệnh đề tương lai giữ nguyên. Ở đây mệnh lệnh 'Charge your phone tonight' chuyển thành 'if you don't charge your phone tonight', còn phần kết quả 'it will die during the trip tomorrow' không đổi. Đáp án đầy đủ: If you don't charge your phone tonight, it will die during the trip tomorrow."},
  {"id":"rw-130","cat":"imperative-or","catLabel":"Mệnh lệnh + or ↔ If ... not / Unless","orig":"Water the plants twice a week, or they will wither in this heat.","stem":"Unless you","answer":"water the plants twice a week, they will wither in this heat","accept":["water the plants twice a week, they will wither in this heat","water the plants twice a week they will wither in this heat","water the plants twice a week, they'll wither in this heat","water the plants twice a week they'll wither in this heat"],"vi":"Mệnh lệnh + or → Unless — bản thân Unless đã mang nghĩa phủ định","explanation":"Công thức: [Mệnh lệnh], or + mệnh đề tương lai = Unless + S + V (chia khẳng định, KHÔNG thêm don't/doesn't vì Unless = If...not), mệnh đề tương lai giữ nguyên. Mệnh lệnh 'Water the plants twice a week' chuyển thành 'unless you water the plants twice a week' — chú ý không có 'don't' vì nghĩa phủ định đã nằm sẵn trong Unless. Đáp án đầy đủ: Unless you water the plants twice a week, they will wither in this heat."},
  {"id":"rw-131","cat":"imperative-or","catLabel":"Mệnh lệnh + or ↔ If ... not / Unless","orig":"Submit your assignment by Friday, or your teacher will deduct marks.","stem":"If you don't","answer":"submit your assignment by Friday, your teacher will deduct marks","accept":["submit your assignment by friday, your teacher will deduct marks","submit your assignment by friday your teacher will deduct marks","submit your assignment by friday, your teacher will deduct your marks","submit your assignment by friday your teacher will deduct your marks"],"vi":"Mệnh lệnh + or → If ... don't — chủ ngữ mệnh đề kết quả khác 'you'","explanation":"Công thức không đổi: [Mệnh lệnh], or + mệnh đề tương lai = If + S + don't/doesn't + V, mệnh đề tương lai giữ nguyên (kể cả khi chủ ngữ mệnh đề kết quả là 'your teacher' chứ không phải 'you'). Chỉ mệnh lệnh 'Submit your assignment by Friday' được chuyển thành 'if you don't submit your assignment by Friday'. Đáp án đầy đủ: If you don't submit your assignment by Friday, your teacher will deduct marks."},
  {"id":"rw-132","cat":"imperative-or","catLabel":"Mệnh lệnh + or ↔ If ... not / Unless","orig":"Save your work every ten minutes, or you will lose your essay.","stem":"Unless you","answer":"save your work every ten minutes, you will lose your essay","accept":["save your work every ten minutes, you will lose your essay","save your work every ten minutes you will lose your essay","save your work every ten minutes, you'll lose your essay","save your work every ten minutes you'll lose your essay"],"vi":"Mệnh lệnh + or → Unless — cụm trạng từ tần suất trong mệnh đề","explanation":"Công thức: [Mệnh lệnh], or + mệnh đề tương lai = Unless + S + V (khẳng định) + mệnh đề tương lai giữ nguyên, kể cả khi mệnh lệnh có cụm trạng từ tần suất như 'every ten minutes' — cụm này đi liền sau động từ, không bị tách rời. Mệnh lệnh 'Save your work every ten minutes' chuyển thành 'unless you save your work every ten minutes'. Đáp án đầy đủ: Unless you save your work every ten minutes, you will lose your essay."},
  {"id":"rw-133","cat":"imperative-or","catLabel":"Mệnh lệnh + or ↔ If ... not / Unless","orig":"Apologize to her right now, or she won't forgive you.","stem":"If you don't","answer":"apologize to her right now, she won't forgive you","accept":["apologize to her right now, she won't forgive you","apologize to her right now she won't forgive you","apologize to her right now, she will not forgive you","apologize to her right now she will not forgive you"],"vi":"Mệnh lệnh + or → If ... don't — mệnh đề kết quả đã ở dạng phủ định","explanation":"Công thức vẫn là If + S + don't + V (từ mệnh lệnh), + mệnh đề tương lai — nhưng cần lưu ý mệnh đề kết quả 'she won't forgive you' trong câu gốc VỐN ĐÃ phủ định nên giữ nguyên 'won't', không đổi thành khẳng định. Mệnh lệnh 'Apologize to her right now' chuyển thành 'if you don't apologize to her right now'. Đáp án đầy đủ: If you don't apologize to her right now, she won't forgive you."},
  {"id":"rw-134","cat":"imperative-or","catLabel":"Mệnh lệnh + or ↔ If ... not / Unless","orig":"Reduce your screen time, or your eyesight might get worse.","stem":"Unless you","answer":"reduce your screen time, your eyesight might get worse","accept":["reduce your screen time, your eyesight might get worse","reduce your screen time your eyesight might get worse"],"vi":"Mệnh lệnh + or → Unless — mệnh đề kết quả dùng động từ khuyết thiếu 'might'","explanation":"Công thức: [Mệnh lệnh], or + mệnh đề (dùng modal verb) = Unless + S + V (khẳng định), mệnh đề đó giữ nguyên modal verb 'might' — không đổi thành 'will'. Mệnh lệnh 'Reduce your screen time' chuyển thành 'unless you reduce your screen time'. Đáp án đầy đủ: Unless you reduce your screen time, your eyesight might get worse."},
  {"id":"rw-135","cat":"imperative-or","catLabel":"Mệnh lệnh + or ↔ If ... not / Unless","orig":"Don't touch that exposed wire, or you will get an electric shock.","stem":"If you","answer":"touch that exposed wire, you will get an electric shock","accept":["touch that exposed wire, you will get an electric shock","touch that exposed wire you will get an electric shock","touch that exposed wire, you'll get an electric shock","touch that exposed wire you'll get an electric shock"],"vi":"Mệnh lệnh PHỦ ĐỊNH (Don't) + or → If ... (khẳng định, không thêm don't)","explanation":"Lưu ý đặc biệt: khi mệnh lệnh gốc đã ở dạng phủ định 'Don't + V, or...', ta chuyển thành If + S + V (khẳng định) — KHÔNG thêm 'don't' nữa, vì 'Don't touch, or...' nghĩa là 'nếu bạn chạm vào (việc bị cấm) thì...'. Mệnh lệnh 'Don't touch that exposed wire' chuyển thành 'if you touch that exposed wire'. Đáp án đầy đủ: If you touch that exposed wire, you will get an electric shock."},
  {"id":"rw-136","cat":"imperative-or","catLabel":"Mệnh lệnh + or ↔ If ... not / Unless","orig":"Leave home at 7 a.m., or you will get stuck in traffic and miss your interview.","stem":"Unless you","answer":"leave home at 7 a.m., you will get stuck in traffic and miss your interview","accept":["leave home at 7 a.m., you will get stuck in traffic and miss your interview","leave home at 7 am, you will get stuck in traffic and miss your interview","leave home at 7 a.m. you will get stuck in traffic and miss your interview","leave home at 7 a.m., you'll get stuck in traffic and miss your interview","leave home at 7 am you'll get stuck in traffic and miss your interview"],"vi":"Mệnh lệnh + or → Unless — mệnh đề kết quả nối hai hành động bằng 'and'","explanation":"Công thức: [Mệnh lệnh], or + mệnh đề tương lai = Unless + S + V (khẳng định), mệnh đề tương lai giữ nguyên toàn bộ kể cả khi có hai hành động nối bằng 'and' ('get stuck in traffic and miss your interview'). Mệnh lệnh 'Leave home at 7 a.m.' chuyển thành 'unless you leave home at 7 a.m.'. Đáp án đầy đủ: Unless you leave home at 7 a.m., you will get stuck in traffic and miss your interview."},
  {"id":"rw-137","cat":"if-i-were-you","catLabel":"Lời khuyên → If I were you","orig":"I advise you to drink more water every day.","stem":"If I were","answer":"you, I would drink more water every day","accept":["you, i would drink more water every day","you i would drink more water every day","you, i'd drink more water every day","you, i would drink more water every day."],"vi":"advise sb to V → If I were you — câu điều kiện loại 2 chỉ lời khuyên","explanation":"Khi ai đó khuyên bằng cấu trúc 'advise sb to V', ta có thể chuyển thành câu điều kiện loại 2 'If I were you, I would + V' để diễn đạt lời khuyên một cách nhẹ nhàng, giả định. Động từ nguyên mẫu 'to drink' chuyển thành 'would drink', các thành phần còn lại giữ nguyên. Đáp án đầy đủ: If I were you, I would drink more water every day."},
  {"id":"rw-138","cat":"if-i-were-you","catLabel":"Lời khuyên → If I were you","orig":"I think you should spend less time playing video games and more time studying.","stem":"If I were","answer":"you, I would spend less time playing video games and more time studying","accept":["you, i would spend less time playing video games and more time studying","you i would spend less time playing video games and more time studying","you, i'd spend less time playing video games and more time studying","you, i would spend less time playing video games and more time studying."],"vi":"I think you should V → If I were you — lời khuyên về thói quen","explanation":"Cấu trúc 'I think you should V' cũng dùng để đưa ra lời khuyên, có thể chuyển sang câu điều kiện loại 2 'If I were you, I would + V' để nghe nhẹ nhàng, mang tính giả định hơn. Ở đây 'should spend' chuyển thành 'would spend', cụm 'less time playing video games and more time studying' giữ nguyên vì chỉ là tân ngữ bổ sung. Đáp án đầy đủ: If I were you, I would spend less time playing video games and more time studying."},
  {"id":"rw-139","cat":"if-i-were-you","catLabel":"Lời khuyên → If I were you","orig":"You should apologize to your classmate for what you said yesterday.","stem":"If I were","answer":"you, I would apologize to my classmate for what I said yesterday","accept":["you, i would apologize to my classmate for what i said yesterday","you i would apologize to my classmate for what i said yesterday","you, i'd apologize to my classmate for what i said yesterday","you, i would apologise to my classmate for what i said yesterday","you, i would apologize to my classmate for what i said yesterday."],"vi":"should V → If I were you — đổi đại từ nhân xưng bạn thành tôi","explanation":"'You should V' được chuyển thành 'If I were you, I would V', nhưng vì chủ ngữ giả định bây giờ là 'I' nên mọi từ chỉ 'bạn' trong câu gốc phải đổi sang 'tôi': your classmate → my classmate, you said → I said. Đáp án đầy đủ: If I were you, I would apologize to my classmate for what I said yesterday."},
  {"id":"rw-140","cat":"if-i-were-you","catLabel":"Lời khuyên → If I were you","orig":"My advice is that you should recycle your old textbooks instead of throwing them away.","stem":"If I were","answer":"you, I would recycle my old textbooks instead of throwing them away","accept":["you, i would recycle my old textbooks instead of throwing them away","you i would recycle my old textbooks instead of throwing them away","you, i'd recycle my old textbooks instead of throwing them away","you, i would recycle my old textbooks instead of throwing them away."],"vi":"My advice is that... should → If I were you — đổi 'your' thành 'my'","explanation":"Mệnh đề lời khuyên 'My advice is that you should V' được rút gọn thành 'If I were you, I would + V'. Vì chủ ngữ giả định là 'I' nên tính từ sở hữu 'your old textbooks' phải đổi thành 'my old textbooks', còn phần 'instead of throwing them away' giữ nguyên. Đáp án đầy đủ: If I were you, I would recycle my old textbooks instead of throwing them away."},
  {"id":"rw-141","cat":"if-i-were-you","catLabel":"Lời khuyên → If I were you","orig":"You had better save some money instead of spending it all on clothes.","stem":"If I were","answer":"you, I would save some money instead of spending it all on clothes","accept":["you, i would save some money instead of spending it all on clothes","you i would save some money instead of spending it all on clothes","you, i'd save some money instead of spending it all on clothes","you, i would save some money instead of spending it all on clothes."],"vi":"had better V → If I were you — lời khuyên mạnh","explanation":"'You had better V' mang nghĩa khuyên nhủ khá mạnh, tương đương 'If I were you, I would V'. Động từ nguyên mẫu 'save' giữ nguyên sau 'would', các cụm còn lại không đổi vì không có đại từ sở hữu. Đáp án đầy đủ: If I were you, I would save some money instead of spending it all on clothes."},
  {"id":"rw-142","cat":"if-i-were-you","catLabel":"Lời khuyên → If I were you","orig":"Why don't you ask your teacher for help with the difficult exercises?","stem":"If I were","answer":"you, I would ask my teacher for help with the difficult exercises","accept":["you, i would ask my teacher for help with the difficult exercises","you i would ask my teacher for help with the difficult exercises","you, i'd ask my teacher for help with the difficult exercises","you, i would ask my teacher for help with the difficult exercises."],"vi":"Why don't you...? → If I were you — câu gợi ý đổi sang lời khuyên","explanation":"Câu gợi ý 'Why don't you V?' có nghĩa tương đương lời khuyên 'You should V', nên chuyển thành 'If I were you, I would V'. Đồng thời đại từ sở hữu 'your teacher' đổi thành 'my teacher' vì chủ ngữ giả định là 'I'. Đáp án đầy đủ: If I were you, I would ask my teacher for help with the difficult exercises."},
  {"id":"rw-143","cat":"if-i-were-you","catLabel":"Lời khuyên → If I were you","orig":"I advise you not to stay up late before the exam.","stem":"If I were","answer":"you, I would not stay up late before the exam","accept":["you, i would not stay up late before the exam","you i would not stay up late before the exam","you, i wouldn't stay up late before the exam","you, i would not stay up late before the exam."],"vi":"advise sb not to V → If I were you, I would not V — lời khuyên phủ định","explanation":"Khi lời khuyên ở dạng phủ định 'advise sb not to V', câu điều kiện loại 2 tương ứng là 'If I were you, I would not/wouldn't + V'. Phần phủ định đặt ngay sau 'would'. Đáp án đầy đủ: If I were you, I would not stay up late before the exam."},
  {"id":"rw-144","cat":"if-i-were-you","catLabel":"Lời khuyên → If I were you","orig":"You ought to tell your parents about the problem instead of hiding it from them.","stem":"If I were","answer":"you, I would tell my parents about the problem instead of hiding it from them","accept":["you, i would tell my parents about the problem instead of hiding it from them","you i would tell my parents about the problem instead of hiding it from them","you, i'd tell my parents about the problem instead of hiding it from them","you, i would tell my parents about the problem instead of hiding it from them."],"vi":"ought to V → If I were you — lời khuyên trang trọng, đổi đại từ sở hữu","explanation":"'You ought to V' tương đương 'You should V', được chuyển thành 'If I were you, I would V'. Vì chủ ngữ giả định là 'I' nên 'your parents' đổi thành 'my parents', còn cụm 'instead of hiding it from them' giữ nguyên vì 'them' vẫn chỉ cha mẹ, không cần đổi. Đáp án đầy đủ: If I were you, I would tell my parents about the problem instead of hiding it from them."},
  {"id":"rw-145","cat":"it-takes","catLabel":"It takes sb + time + to V ↔ spend + time + V-ing","orig":"Lan spends thirty minutes cycling to school every morning.","stem":"It takes","answer":"Lan thirty minutes to cycle to school every morning","accept":["lan thirty minutes to cycle to school every morning","lan thirty minutes to cycle to school every morning.","lan 30 minutes to cycle to school every morning","lan thirty minutes to cycle to school"],"vi":"spend + time + V-ing ↔ It takes + sb + time + to V — thì hiện tại đơn","explanation":"Cấu trúc 'S + spend + thời gian + V-ing' tương đương với 'It takes + sb + thời gian + to V'. Ở đây 'Lan spends thirty minutes cycling to school' chuyển thành 'It takes Lan thirty minutes to cycle to school', giữ nguyên thì hiện tại đơn và trạng ngữ 'every morning' ở cuối câu. Đáp án đầy đủ: It takes Lan thirty minutes to cycle to school every morning."},
  {"id":"rw-146","cat":"it-takes","catLabel":"It takes sb + time + to V ↔ spend + time + V-ing","orig":"It takes Mr. Brown an hour to prepare dinner for his family every evening.","stem":"Mr. Brown spends","answer":"an hour preparing dinner for his family every evening","accept":["an hour preparing dinner for his family every evening","an hour preparing dinner for his family every evening.","1 hour preparing dinner for his family every evening","an hour preparing dinner for his family"],"vi":"It takes + sb + time + to V ↔ spend + time + V-ing — thì hiện tại đơn","explanation":"Khi đổi từ 'It takes + sb + thời gian + to V' sang 'S + spend + thời gian + V-ing', động từ nguyên mẫu có 'to' chuyển thành V-ing. Câu 'It takes Mr. Brown an hour to prepare dinner for his family' trở thành 'Mr. Brown spends an hour preparing dinner for his family', trạng ngữ 'every evening' giữ nguyên ở cuối. Đáp án đầy đủ: Mr. Brown spends an hour preparing dinner for his family every evening."},
  {"id":"rw-147","cat":"it-takes","catLabel":"It takes sb + time + to V ↔ spend + time + V-ing","orig":"My sister spends two hours studying for her exams every night.","stem":"It takes","answer":"my sister two hours to study for her exams every night","accept":["my sister two hours to study for her exams every night","my sister 2 hours to study for her exams every night","my sister two hours to study for her exams every night.","my sister two hours to study for her exams"],"vi":"spend + time + V-ing ↔ It takes + sb + time + to V — thì hiện tại đơn","explanation":"Chủ ngữ 'My sister' chuyển thành tân ngữ đứng sau 'It takes', và động từ V-ing 'studying' trở về dạng nguyên mẫu có 'to': 'to study'. Câu gốc 'My sister spends two hours studying for her exams' thành 'It takes my sister two hours to study for her exams'. Đáp án đầy đủ: It takes my sister two hours to study for her exams every night."},
  {"id":"rw-148","cat":"it-takes","catLabel":"It takes sb + time + to V ↔ spend + time + V-ing","orig":"It took the workers three days to repair the old bridge.","stem":"The workers spent","answer":"three days repairing the old bridge","accept":["three days repairing the old bridge","3 days repairing the old bridge","three days repairing the old bridge."],"vi":"It takes + sb + time + to V ↔ spend + time + V-ing — thì quá khứ đơn","explanation":"Ở thì quá khứ, 'It took + sb + thời gian + to V' tương đương 'S + spent + thời gian + V-ing' ('took' và 'spent' đều là dạng quá khứ). Động từ 'to repair' chuyển thành 'repairing'. Đáp án đầy đủ: The workers spent three days repairing the old bridge."},
  {"id":"rw-149","cat":"it-takes","catLabel":"It takes sb + time + to V ↔ spend + time + V-ing","orig":"Tom spent a whole week reading that thick novel.","stem":"It took","answer":"Tom a whole week to read that thick novel","accept":["tom a whole week to read that thick novel","tom a whole week to read that thick novel.","tom a week to read that thick novel"],"vi":"spend + time + V-ing ↔ It takes + sb + time + to V — thì quá khứ đơn","explanation":"'Tom spent a whole week reading that novel' đổi thành 'It took Tom a whole week to read that novel', trong đó 'reading' quay về dạng 'to read'. Giữ nguyên cụm chỉ thời lượng 'a whole week'. Đáp án đầy đủ: It took Tom a whole week to read that thick novel."},
  {"id":"rw-150","cat":"it-takes","catLabel":"It takes sb + time + to V ↔ spend + time + V-ing","orig":"It doesn't take Nam much time to water the plants in the garden every afternoon.","stem":"Nam doesn't spend","answer":"much time watering the plants in the garden every afternoon","accept":["much time watering the plants in the garden every afternoon","much time watering the plants in the garden every afternoon.","a lot of time watering the plants in the garden every afternoon","much time watering the plants in the garden"],"vi":"It takes + sb + time + to V (phủ định) ↔ spend + time + V-ing (phủ định) — thì hiện tại đơn","explanation":"Ở dạng phủ định, 'It doesn't take + sb + much time + to V' chuyển thành 'S + doesn't spend + much time + V-ing'. Ta đổi 'to water' thành 'watering', giữ nguyên 'much time' và trạng ngữ 'in the garden every afternoon'. Đáp án đầy đủ: Nam doesn't spend much time watering the plants in the garden every afternoon."},
  {"id":"rw-151","cat":"it-takes","catLabel":"It takes sb + time + to V ↔ spend + time + V-ing","orig":"How long does it take you to practice badminton with your friends after school?","stem":"How much time do you spend","answer":"practicing badminton with your friends after school","accept":["practicing badminton with your friends after school","practicing badminton with your friends after school?","practising badminton with your friends after school"],"vi":"How long does it take + sb + to V? ↔ How much time do + sb + spend + V-ing? — câu hỏi","explanation":"Với câu hỏi, 'How long does it take you to V?' viết lại thành 'How much time do you spend V-ing?'. Động từ 'to practice' chuyển thành 'practicing', cụm 'with your friends after school' giữ nguyên ở cuối câu. Đáp án đầy đủ: How much time do you spend practicing badminton with your friends after school?"},
  {"id":"rw-152","cat":"it-takes","catLabel":"It takes sb + time + to V ↔ spend + time + V-ing","orig":"The class will spend a whole month rehearsing for the Teachers' Day performance.","stem":"It will take","answer":"the class a whole month to rehearse for the Teachers' Day performance","accept":["the class a whole month to rehearse for the teachers' day performance","the class a whole month to rehearse for the teachers day performance","the class a month to rehearse for the teachers' day performance"],"vi":"spend + time + V-ing ↔ It takes + sb + time + to V — thì tương lai đơn","explanation":"Ở thì tương lai, 'S + will spend + thời gian + V-ing' tương đương 'It will take + sb + thời gian + to V'. Ta đổi 'rehearsing' thành 'to rehearse', và 'the class' trở thành tân ngữ đứng sau 'take'. Đáp án đầy đủ: It will take the class a whole month to rehearse for the Teachers' Day performance."},
  {"id":"rw-153","cat":"keen-on","catLabel":"Like/love ↔ be keen on / interested in + V-ing","orig":"Linh loves listening to podcasts before going to bed.","stem":"Linh is keen","answer":"on listening to podcasts before going to bed","accept":["on listening to podcasts before going to bed","on listening to podcasts before going to bed.","on listening to podcasts before bed","on listening to podcasts"],"vi":"like/love + V-ing → be keen on + V-ing","explanation":"Khi câu gốc dùng 'like/love + V-ing' để nói về sở thích, ta viết lại bằng cấu trúc 'S + am/is/are + keen on + V-ing' mà nghĩa không đổi. Chủ ngữ 'Linh' số ít nên dùng 'is', trạng ngữ thời gian 'before going to bed' vẫn giữ nguyên ở cuối câu. Đáp án đầy đủ: Linh is keen on listening to podcasts before going to bed."},
  {"id":"rw-154","cat":"keen-on","catLabel":"Like/love ↔ be keen on / interested in + V-ing","orig":"The new student likes playing badminton with his classmates every weekend.","stem":"The new student is interested","answer":"in playing badminton with his classmates every weekend","accept":["in playing badminton with his classmates every weekend","in playing badminton with his classmates every weekend.","in playing badminton with his classmates"],"vi":"like + V-ing → be interested in + V-ing","explanation":"Cấu trúc 'like + V-ing' có thể thay bằng 'be interested in + V-ing' mà không đổi nghĩa 'thích làm gì'. Chủ ngữ số ít 'the new student' đi với 'is', sau 'interested' bắt buộc dùng giới từ 'in' rồi mới đến V-ing. Đáp án đầy đủ: The new student is interested in playing badminton with his classmates every weekend."},
  {"id":"rw-155","cat":"keen-on","catLabel":"Like/love ↔ be keen on / interested in + V-ing","orig":"We love growing vegetables in our small garden.","stem":"We are keen","answer":"on growing vegetables in our small garden","accept":["on growing vegetables in our small garden","on growing vegetables in our small garden."],"vi":"love + V-ing → be keen on + V-ing (chủ ngữ số nhiều)","explanation":"Động từ 'love' chỉ sở thích chuyển thành 'be keen on + V-ing'; vì chủ ngữ là 'we' (số nhiều) nên dùng 'are', không phải 'is'. Cụm 'in our small garden' là trạng ngữ nơi chốn, giữ nguyên ở cuối câu (không đổi 'our' thành 'the' vì sẽ làm sai nghĩa sở hữu). Đáp án đầy đủ: We are keen on growing vegetables in our small garden."},
  {"id":"rw-156","cat":"keen-on","catLabel":"Like/love ↔ be keen on / interested in + V-ing","orig":"The tourists are interested in taking photos of ancient temples.","stem":"The tourists like","answer":"taking photos of ancient temples","accept":["taking photos of ancient temples","taking photos of ancient temples.","taking pictures of ancient temples"],"vi":"be interested in + V-ing → like + V-ing (chiều ngược lại)","explanation":"Ở chiều ngược lại, 'be interested in + V-ing' có thể rút gọn thành 'like + V-ing' vì cả hai đều diễn tả sự yêu thích một hoạt động; chỉ cần bỏ 'are interested in' và thay bằng 'like'. Phần còn lại của câu (không có mạo từ 'the' trước 'ancient temples' vì câu gốc nói chung chung) giữ nguyên. Đáp án đầy đủ: The tourists like taking photos of ancient temples."},
  {"id":"rw-157","cat":"keen-on","catLabel":"Like/love ↔ be keen on / interested in + V-ing","orig":"When she was a child, Mai loved collecting colorful stamps from foreign countries.","stem":"When she was a child, Mai was keen","answer":"on collecting colorful stamps from foreign countries","accept":["on collecting colorful stamps from foreign countries","on collecting colorful stamps from foreign countries.","on collecting colourful stamps from foreign countries"],"vi":"loved + V-ing (quá khứ) → was/were keen on + V-ing","explanation":"Vì mốc thời gian là quá khứ ('when she was a child'), 'love' chuyển thành 'was keen on + V-ing' với tobe chia quá khứ. Chủ ngữ 'Mai' số ít nên dùng 'was', theo sau là 'keen on' + V-ing và toàn bộ cụm danh từ 'colorful stamps from foreign countries' được giữ nguyên để không mất chi tiết miêu tả. Đáp án đầy đủ: When she was a child, Mai was keen on collecting colorful stamps from foreign countries."},
  {"id":"rw-158","cat":"keen-on","catLabel":"Like/love ↔ be keen on / interested in + V-ing","orig":"The villagers were keen on preserving their traditional festival every spring.","stem":"The villagers loved","answer":"preserving their traditional festival every spring","accept":["preserving their traditional festival every spring","preserving their traditional festival every spring.","preserving their traditional festival"],"vi":"were keen on + V-ing → loved + V-ing (số nhiều, quá khứ)","explanation":"Câu gốc dùng 'were keen on + V-ing' ở thì quá khứ với chủ ngữ số nhiều 'the villagers'; khi chuyển sang 'love', ta chia quá khứ thành 'loved' và bỏ giới từ 'on'. Trạng ngữ 'every spring' vẫn giữ nguyên ở cuối câu. Đáp án đầy đủ: The villagers loved preserving their traditional festival every spring."},
  {"id":"rw-159","cat":"keen-on","catLabel":"Like/love ↔ be keen on / interested in + V-ing","orig":"Duc likes practicing speaking English with foreign tourists because he wants to improve his pronunciation.","stem":"Duc is keen","answer":"on practicing speaking English with foreign tourists because he wants to improve his pronunciation","accept":["on practicing speaking english with foreign tourists because he wants to improve his pronunciation","on practicing speaking english with foreign tourists because he wants to improve his pronunciation.","on practicing speaking english with foreign tourists","on practising speaking english with foreign tourists because he wants to improve his pronunciation"],"vi":"like + V-ing (+ mệnh đề lý do) → be keen on + V-ing","explanation":"'Like + V-ing' chuyển thành 'be keen on + V-ing'; mệnh đề lý do 'because he wants to improve his pronunciation' chỉ bổ sung thông tin nên được giữ nguyên phía sau, không cần biến đổi. Chủ ngữ 'Duc' số ít dùng 'is'. Đáp án đầy đủ: Duc is keen on practicing speaking English with foreign tourists because he wants to improve his pronunciation."},
  {"id":"rw-160","cat":"keen-on","catLabel":"Like/love ↔ be keen on / interested in + V-ing","orig":"My cousin loves volunteering at the animal shelter on weekends since she adopted a rescue dog last year.","stem":"My cousin is keen","answer":"on volunteering at the animal shelter on weekends since she adopted a rescue dog last year","accept":["on volunteering at the animal shelter on weekends since she adopted a rescue dog last year","on volunteering at the animal shelter on weekends since she adopted a rescue dog last year.","on volunteering at the animal shelter on weekends"],"vi":"love + V-ing (+ mệnh đề since) → be keen on + V-ing","explanation":"Đây là câu dài có mệnh đề 'since she adopted a rescue dog last year' bổ sung thời điểm/lý do; ta chỉ cần chuyển phần chính 'loves volunteering' thành 'is keen on volunteering' và giữ nguyên toàn bộ phần còn lại. Chủ ngữ số ít 'my cousin' dùng 'is'. Đáp án đầy đủ: My cousin is keen on volunteering at the animal shelter on weekends since she adopted a rescue dog last year."},
  {"id":"rw-161","cat":"suggest","catLabel":"Why don't we / Shall we ↔ suggest + V-ing","orig":"\"Why don't we watch a movie together tonight?\" said Peter.","stem":"Peter suggested","answer":"watching a movie together tonight","accept":["watching a movie together tonight","watching a movie together","watching a film together tonight"],"vi":"Why don't we...? → suggest + V-ing — rủ rê giải trí","explanation":"Với câu đề nghị dạng \"Why don't we + V?\", khi viết lại ta dùng công thức: S + suggested + V-ing (bỏ chủ ngữ \"we\" vì người đề nghị đã có trong nghĩa của \"suggested\"). Câu gốc \"Why don't we watch a movie together tonight?\" chuyển thành \"Peter suggested watching a movie together tonight.\" Đáp án đầy đủ giữ cả trạng ngữ thời gian \"tonight\" ở cuối câu."},
  {"id":"rw-162","cat":"suggest","catLabel":"Why don't we / Shall we ↔ suggest + V-ing","orig":"\"Shall we take a short break before the next lesson?\" said the teacher.","stem":"The teacher suggested","answer":"taking a short break before the next lesson","accept":["taking a short break before the next lesson","taking a short break","having a short break before the next lesson"],"vi":"Shall we...? → suggest + V-ing — nghỉ giải lao","explanation":"\"Shall we + V?\" cũng mang nghĩa đề nghị giống \"Why don't we...?\", nên khi tường thuật ta chuyển thành \"suggested + V-ing\". Ở đây \"Shall we take a short break before the next lesson?\" → \"The teacher suggested taking a short break before the next lesson.\" Chú ý bỏ chủ ngữ \"we\", chỉ giữ động từ chia V-ing và phần còn lại của câu."},
  {"id":"rw-163","cat":"suggest","catLabel":"Why don't we / Shall we ↔ suggest + V-ing","orig":"\"Why don't we organize a mini sports day for our class this term?\" said Nam.","stem":"Nam suggested","answer":"organizing a mini sports day for our class this term","accept":["organizing a mini sports day for our class this term","organizing a mini sports day for the class","organising a mini sports day for our class this term"],"vi":"Why don't we...? → suggest + V-ing — tổ chức hoạt động thể thao","explanation":"Áp dụng công thức \"Why don't we + V?\" → \"S + suggested + V-ing\": động từ \"organize\" chuyển thành \"organizing\", các thành phần còn lại giữ nguyên vị trí. Câu gốc Nam đề nghị tổ chức một ngày hội thao nhỏ cho lớp trong học kỳ này nên viết lại là \"Nam suggested organizing a mini sports day for our class this term.\" Lưu ý \"organize\" (Anh-Mỹ) và \"organise\" (Anh-Anh) đều đúng chính tả và được chấp nhận."},
  {"id":"rw-164","cat":"suggest","catLabel":"Why don't we / Shall we ↔ suggest + V-ing","orig":"\"Shall we ask the teacher for advice on this problem?\" said Mai.","stem":"Mai suggested","answer":"asking the teacher for advice on this problem","accept":["asking the teacher for advice on this problem","asking the teacher for advice","asking the teacher for some advice on this problem"],"vi":"Shall we...? → suggest + V-ing — nhờ giúp đỡ","explanation":"Khi câu trực tiếp là lời đề nghị dạng \"Shall we + V?\", ta chuyển thành \"suggested + V-ing\", các thành phần còn lại (tân ngữ, giới từ) giữ nguyên vị trí. Câu này trở thành \"Mai suggested asking the teacher for advice on this problem.\" Đáp án đầy đủ: asking the teacher for advice on this problem."},
  {"id":"rw-165","cat":"suggest","catLabel":"Why don't we / Shall we ↔ suggest + V-ing","orig":"\"Why don't we recycle these old newspapers instead of throwing them away?\" said Lan.","stem":"Lan suggested","answer":"recycling these old newspapers instead of throwing them away","accept":["recycling these old newspapers instead of throwing them away","recycling the old newspapers instead of throwing them away","recycling these old newspapers"],"vi":"Why don't we...? → suggest + V-ing — tái chế, bảo vệ môi trường","explanation":"Áp dụng công thức \"Why don't we + V?\" → \"S + suggested + V-ing\", động từ \"recycle\" chuyển thành \"recycling\", cụm từ phía sau \"instead of throwing them away\" giữ nguyên vì nó bổ sung lý do cho lời đề nghị. Câu hoàn chỉnh: \"Lan suggested recycling these old newspapers instead of throwing them away.\""},
  {"id":"rw-166","cat":"suggest","catLabel":"Why don't we / Shall we ↔ suggest + V-ing","orig":"\"Why don't we decorate the classroom for the New Year festival?\" said the students.","stem":"The students suggested","answer":"decorating the classroom for the New Year festival","accept":["decorating the classroom for the new year festival","decorating the class for the new year festival","decorating the classroom for new year"],"vi":"Why don't we...? → suggest + V-ing — trang trí dịp lễ hội","explanation":"Chuyển \"Why don't we decorate...?\" thành \"suggested decorating...\", giữ nguyên tân ngữ \"the classroom\" và trạng ngữ mục đích \"for the New Year festival\". Câu viết lại: \"The students suggested decorating the classroom for the New Year festival.\" Đây là dạng đề nghị của một nhóm người nên chủ ngữ tường thuật là \"the students\"."},
  {"id":"rw-167","cat":"suggest","catLabel":"Why don't we / Shall we ↔ suggest + V-ing","orig":"\"Shall we limit screen time before going to bed?\" said the doctor.","stem":"The doctor suggested","answer":"limiting screen time before going to bed","accept":["limiting screen time before going to bed","limiting screen time","limiting the screen time before going to bed"],"vi":"Shall we...? → suggest + V-ing — lời khuyên sức khỏe","explanation":"Lời khuyên dạng \"Shall we + V?\" của bác sĩ được viết lại bằng \"suggested + V-ing\". Động từ \"limit\" → \"limiting\", cụm trạng ngữ thời gian \"before going to bed\" giữ nguyên vị trí cuối câu. Đáp án: limiting screen time before going to bed."},
  {"id":"rw-168","cat":"suggest","catLabel":"Why don't we / Shall we ↔ suggest + V-ing","orig":"\"Shall we not tell Anna about the surprise party yet?\" said Kate.","stem":"Kate suggested","answer":"not telling Anna about the surprise party yet","accept":["not telling anna about the surprise party yet","not telling anna about the surprise party","not telling her about the surprise party yet"],"vi":"Shall we not...? → suggest + not V-ing — đề nghị phủ định","explanation":"Đây là dạng nâng cao: khi câu đề nghị mang ý phủ định \"Shall we not + V?\", ta chuyển thành \"suggested + not + V-ing\" (thêm \"not\" ngay trước V-ing). Câu gốc \"Shall we not tell Anna about the surprise party yet?\" → \"Kate suggested not telling Anna about the surprise party yet.\" Đây là điểm khác biệt cần lưu ý so với các câu suggest khẳng định ở trên."},
  {"id":"rw-169","cat":"because-of","catLabel":"Because + mệnh đề ↔ Because of + danh từ/V-ing","orig":"Because the traffic was very heavy this morning, Minh arrived late for the meeting.","stem":"Because of","answer":"the very heavy traffic this morning, Minh arrived late for the meeting","accept":["the very heavy traffic this morning, minh arrived late for the meeting","the very heavy traffic this morning minh arrived late for the meeting","very heavy traffic this morning, minh arrived late for the meeting","very heavy traffic this morning minh arrived late for the meeting"],"vi":"Because + mệnh đề → Because of + danh từ (tính từ + danh từ)","explanation":"Công thức: 'Because + S + V' đổi thành 'Because of + cụm danh từ'; tính từ làm vị ngữ trong mệnh đề chuyển thành tính từ đứng trước danh từ: 'the traffic was very heavy' → 'the very heavy traffic'. Vế còn lại (Minh arrived late for the meeting) giữ nguyên. Đáp án đầy đủ: 'Because of the very heavy traffic this morning, Minh arrived late for the meeting.'"},
  {"id":"rw-170","cat":"because-of","catLabel":"Because + mệnh đề ↔ Because of + danh từ/V-ing","orig":"Because of her lack of experience, Trang was not chosen for the marketing position.","stem":"Because","answer":"she lacked experience, Trang was not chosen for the marketing position","accept":["she lacked experience, trang was not chosen for the marketing position","she did not have experience, trang was not chosen for the marketing position","she didn't have experience, trang was not chosen for the marketing position","she had no experience, trang was not chosen for the marketing position"],"vi":"Because of + danh từ → Because + mệnh đề","explanation":"Công thức: 'Because of + danh từ' chuyển thành 'Because + S + V'; cụm danh từ 'her lack of experience' được khôi phục thành mệnh đề với động từ tương ứng: 'lack of' → 'lacked' (hoặc 'did not have'/'had no'). Đáp án đầy đủ: 'Because she lacked experience, Trang was not chosen for the marketing position.'"},
  {"id":"rw-171","cat":"because-of","catLabel":"Because + mệnh đề ↔ Because of + danh từ/V-ing","orig":"Because Nam practiced speaking English every day, he improved his pronunciation quickly.","stem":"Because of","answer":"practicing speaking English every day, Nam improved his pronunciation quickly","accept":["practicing speaking english every day, nam improved his pronunciation quickly","practicing speaking english every day nam improved his pronunciation quickly"],"vi":"Because + mệnh đề (cùng chủ ngữ) → Because of + V-ing","explanation":"Khi hai mệnh đề có cùng chủ ngữ, ta bỏ chủ ngữ và chia động từ ở dạng V-ing ngay sau 'Because of': 'Nam practiced' → 'practicing'. Vế chính giữ nguyên, chủ ngữ 'Nam' đứng ngay sau cụm V-ing. Đáp án đầy đủ: 'Because of practicing speaking English every day, Nam improved his pronunciation quickly.'"},
  {"id":"rw-172","cat":"because-of","catLabel":"Because + mệnh đề ↔ Because of + danh từ/V-ing","orig":"Many students feel sleepy in class because of staying up late playing video games.","stem":"Many students feel sleepy in class because","answer":"they stay up late playing video games","accept":["they stay up late playing video games","they stay up late playing videogames"],"vi":"Because of + V-ing → Because + mệnh đề","explanation":"Cụm 'Because of + V-ing' được khôi phục thành mệnh đề bằng cách thêm chủ ngữ và chia động từ theo đúng thì của mệnh đề chính (hiện tại đơn, vì 'feel' chia hiện tại đơn): 'staying up late' → 'they stay up late'. Đáp án đầy đủ: 'Many students feel sleepy in class because they stay up late playing video games.'"},
  {"id":"rw-173","cat":"because-of","catLabel":"Because + mệnh đề ↔ Because of + danh từ/V-ing","orig":"Because the company invested heavily in research, it launched an innovative product this year.","stem":"Because of","answer":"the company's heavy investment in research, it launched an innovative product this year","accept":["the company's heavy investment in research, it launched an innovative product this year","the company's heavy investment in research it launched an innovative product this year","its heavy investment in research, it launched an innovative product this year","its heavy investment in research it launched an innovative product this year","the companys heavy investment in research, it launched an innovative product this year"],"vi":"Because + mệnh đề → Because of + danh từ sở hữu (danh từ hoá động từ)","explanation":"Động từ + trạng từ 'invested heavily' chuyển thành cụm danh từ 'heavy investment'; chủ ngữ 'the company' chuyển thành sở hữu cách 'the company's' để đại từ 'it' ở vế chính có nghĩa rõ ràng (không bị mất chủ thể). Đáp án đầy đủ: 'Because of the company's heavy investment in research, it launched an innovative product this year.'"},
  {"id":"rw-174","cat":"because-of","catLabel":"Because + mệnh đề ↔ Because of + danh từ/V-ing","orig":"Because of the shortage of clean water, many villagers suffer from serious health problems.","stem":"Because","answer":"there is a shortage of clean water, many villagers suffer from serious health problems","accept":["there is a shortage of clean water, many villagers suffer from serious health problems","there's a shortage of clean water, many villagers suffer from serious health problems","clean water is in short supply, many villagers suffer from serious health problems"],"vi":"Because of + danh từ (there is/are) → Because + mệnh đề","explanation":"Với danh từ chỉ số lượng như 'shortage', ta khôi phục mệnh đề bằng cấu trúc 'there is/are a shortage of + N'. Vế chính giữ nguyên ở thì hiện tại đơn để khớp với 'suffer'. Đáp án đầy đủ: 'Because there is a shortage of clean water, many villagers suffer from serious health problems.'"},
  {"id":"rw-175","cat":"because-of","catLabel":"Because + mệnh đề ↔ Because of + danh từ/V-ing","orig":"Because the lead singer suddenly fell seriously ill, the concert was postponed until next month.","stem":"Because of","answer":"the lead singer's sudden serious illness, the concert was postponed until next month","accept":["the lead singer's sudden serious illness, the concert was postponed until next month","the lead singers sudden serious illness, the concert was postponed until next month","the lead singer's sudden serious illness the concert was postponed until next month"],"vi":"Because + mệnh đề → Because of + danh từ sở hữu","explanation":"Chủ ngữ của mệnh đề chuyển thành sở hữu cách: 'the lead singer' → 'the lead singer's'; cụm trạng từ + tính từ 'suddenly...seriously ill' chuyển thành cụm tính từ + danh từ 'sudden serious illness' ('fell ill' → 'illness'). Đáp án đầy đủ: 'Because of the lead singer's sudden serious illness, the concert was postponed until next month.'"},
  {"id":"rw-176","cat":"because-of","catLabel":"Because + mệnh đề ↔ Because of + danh từ/V-ing","orig":"Because of not checking the weather forecast beforehand, the group got caught in a violent storm during their camping trip.","stem":"Because","answer":"they did not check the weather forecast beforehand, the group got caught in a violent storm during their camping trip","accept":["they did not check the weather forecast beforehand, the group got caught in a violent storm during their camping trip","they didn't check the weather forecast beforehand, the group got caught in a violent storm during their camping trip","the group did not check the weather forecast beforehand, the group got caught in a violent storm during their camping trip","the group didn't check the weather forecast beforehand, the group got caught in a violent storm during their camping trip"],"vi":"Because of + V-ing phủ định → Because + mệnh đề phủ định","explanation":"'not + V-ing' được khôi phục thành mệnh đề phủ định 'S + did not/didn't + V' ở thì quá khứ đơn, khớp với mệnh đề chính 'got caught': 'not checking' → 'they did not check'. Đáp án đầy đủ: 'Because they did not check the weather forecast beforehand, the group got caught in a violent storm during their camping trip.'"},
  {"id":"rw-177","cat":"would-rather","catLabel":"Prefer + V-ing ↔ would rather + V","orig":"Nam prefers playing football to playing basketball after school.","stem":"Nam would rather","answer":"play football than play basketball after school","accept":["play football than play basketball after school","play football than play basketball"],"vi":"prefer V-ing ↔ would rather V — sở thích trong sinh hoạt hằng ngày","explanation":"Cấu trúc \"S + prefer + V-ing + to + V-ing\" (thích cái này hơn cái kia) chuyển sang \"S + would rather + V (nguyên mẫu không \"to\") + than + V\" mà nghĩa không đổi. Ở đây \"playing football\" và \"playing basketball\" bỏ đuôi \"-ing\" thành \"play football\" và \"play basketball\", nối bằng \"than\". Đáp án đầy đủ: Nam would rather play football than play basketball after school."},
  {"id":"rw-178","cat":"would-rather","catLabel":"Prefer + V-ing ↔ would rather + V","orig":"My sister prefers drinking tea to drinking coffee in the morning.","stem":"My sister would rather","answer":"drink tea than drink coffee in the morning","accept":["drink tea than drink coffee in the morning","drink tea than drink coffee"],"vi":"prefer V-ing ↔ would rather V — thói quen ăn uống","explanation":"Áp dụng công thức \"prefer + V-ing + to + V-ing\" → \"would rather + V + than + V\": hai động từ \"drinking\" đều chuyển về dạng nguyên mẫu \"drink\", giữ nguyên trạng ngữ \"in the morning\" ở cuối câu. Đáp án đầy đủ: My sister would rather drink tea than drink coffee in the morning."},
  {"id":"rw-179","cat":"would-rather","catLabel":"Prefer + V-ing ↔ would rather + V","orig":"Our teacher prefers explaining grammar rules to giving us exercises directly.","stem":"Our teacher would rather","answer":"explain grammar rules than give us exercises directly","accept":["explain grammar rules than give us exercises directly","explain grammar rules than give us exercises"],"vi":"prefer V-ing ↔ would rather V — cách dạy học","explanation":"Vẫn là công thức \"prefer + V-ing...to + V-ing...\" → \"would rather + V...than + V...\", chú ý tân ngữ gián tiếp \"us\" vẫn giữ nguyên sau động từ \"give\". Đáp án đầy đủ: Our teacher would rather explain grammar rules than give us exercises directly."},
  {"id":"rw-180","cat":"would-rather","catLabel":"Prefer + V-ing ↔ would rather + V","orig":"Minh prefers doing his homework early to leaving it until the last minute.","stem":"Minh would rather","answer":"do his homework early than leave it until the last minute","accept":["do his homework early than leave it until the last minute","do his homework early than leave it to the last minute"],"vi":"prefer V-ing ↔ would rather V — thói quen học tập","explanation":"Chuyển \"doing his homework early\" thành \"do his homework early\" và \"leaving it until the last minute\" thành \"leave it until the last minute\", nối bằng \"than\", giữ nguyên đại từ \"it\" và \"his\". Đáp án đầy đủ: Minh would rather do his homework early than leave it until the last minute."},
  {"id":"rw-181","cat":"would-rather","catLabel":"Prefer + V-ing ↔ would rather + V","orig":"Our neighbors prefer not using plastic bags to harming the environment.","stem":"Our neighbors would rather","answer":"not use plastic bags than harm the environment","accept":["not use plastic bags than harm the environment","not use plastic bags than damage the environment"],"vi":"prefer not V-ing ↔ would rather not V — dạng phủ định, chủ đề môi trường","explanation":"Khi câu gốc mang ý phủ định \"prefer + not V-ing... to + V-ing...\", ta chuyển thành \"would rather + not + V... than + V...\", từ \"not\" đứng ngay sau \"rather\". Ở đây \"not using plastic bags\" → \"not use plastic bags\" và \"harming the environment\" → \"harm the environment\". Đáp án đầy đủ: Our neighbors would rather not use plastic bags than harm the environment."},
  {"id":"rw-182","cat":"would-rather","catLabel":"Prefer + V-ing ↔ would rather + V","orig":"Because of the traffic jam, David prefers taking the train to driving his car to work.","stem":"Because of the traffic jam, David would rather","answer":"take the train than drive his car to work","accept":["take the train than drive his car to work","take the train than drive his car"],"vi":"prefer V-ing ↔ would rather V — mệnh đề trạng ngữ nguyên nhân","explanation":"Mệnh đề trạng ngữ chỉ nguyên nhân \"Because of the traffic jam\" đứng đầu câu được giữ nguyên, chỉ mệnh đề chính đổi từ \"prefer + V-ing + to + V-ing\" sang \"would rather + V + than + V\". Đáp án đầy đủ: Because of the traffic jam, David would rather take the train than drive his car to work."},
  {"id":"rw-183","cat":"would-rather","catLabel":"Prefer + V-ing ↔ would rather + V","orig":"During the summer holidays, my cousins prefer swimming in the lake to sunbathing on the beach.","stem":"During the summer holidays, my cousins would rather","answer":"swim in the lake than sunbathe on the beach","accept":["swim in the lake than sunbathe on the beach","swim in the lake than sunbathe"],"vi":"prefer V-ing ↔ would rather V — mệnh đề trạng ngữ thời gian","explanation":"Trạng ngữ thời gian \"During the summer holidays\" giữ nguyên vị trí đầu câu; động từ \"swimming\" và \"sunbathing\" trong mệnh đề chính chuyển về nguyên mẫu \"swim\" và \"sunbathe\", nối bằng \"than\". Đáp án đầy đủ: During the summer holidays, my cousins would rather swim in the lake than sunbathe on the beach."},
  {"id":"rw-184","cat":"would-rather","catLabel":"Prefer + V-ing ↔ would rather + V","orig":"The company prefers hiring experienced staff to training fresh graduates from scratch.","stem":"The company would rather","answer":"hire experienced staff than train fresh graduates from scratch","accept":["hire experienced staff than train fresh graduates from scratch","hire experienced staff than train fresh graduates"],"vi":"prefer V-ing ↔ would rather V — ngữ cảnh công việc/kinh doanh","explanation":"Áp dụng đúng công thức \"prefer + V-ing + to + V-ing\" → \"would rather + V + than + V\" với chủ ngữ số ít \"the company\": \"hiring experienced staff\" → \"hire experienced staff\", \"training fresh graduates from scratch\" → \"train fresh graduates from scratch\". Đáp án đầy đủ: The company would rather hire experienced staff than train fresh graduates from scratch."},
  {"id":"rw-185","cat":"first-time","catLabel":"This is the first time ↔ have never ... before","orig":"This is the first time my sister has cooked pho for guests.","stem":"My sister has never","answer":"cooked pho for guests before","accept":["cooked pho for guests before","cooked pho for guests"],"vi":"'This is the first time' + HTHT ↔ 'have/has never' + PII + before","explanation":"Công thức: 'This is the first time + S + have/has + PII' (Đây là lần đầu tiên...) tương đương với 'S + have/has never + PII + before' (Chưa bao giờ... trước đây). Ở câu này ta giữ nguyên chủ ngữ 'my sister' và động từ 'has cooked', chỉ cần chèn 'never' ngay sau 'has' và thêm 'before' ở cuối câu. Đáp án đầy đủ: 'My sister has never cooked pho for guests before.'"},
  {"id":"rw-186","cat":"first-time","catLabel":"This is the first time ↔ have never ... before","orig":"This is the first time our class has taken part in an English speech contest.","stem":"Our class has never","answer":"taken part in an English speech contest before","accept":["taken part in an english speech contest before","taken part in an english speech contest"],"vi":"'This is the first time' + HTHT ↔ 'have/has never' + PII + before","explanation":"Khi gặp mẫu câu 'This is the first time + S + have/has + PII', ta chuyển sang thể phủ định của hiện tại hoàn thành bằng công thức 'S + have/has never + PII + before'. Danh từ tập thể 'our class' đi với 'has', cụm động từ 'taken part in an English speech contest' được giữ nguyên, chỉ thêm 'never' và 'before'. Đáp án đầy đủ: 'Our class has never taken part in an English speech contest before.'"},
  {"id":"rw-187","cat":"first-time","catLabel":"This is the first time ↔ have never ... before","orig":"This is the first time I have used a self-checkout machine at the supermarket.","stem":"I have never","answer":"used a self-checkout machine at the supermarket before","accept":["used a self-checkout machine at the supermarket before","used a self-checkout machine at the supermarket","used a self checkout machine at the supermarket before"],"vi":"'This is the first time' + HTHT ↔ 'have/has never' + PII + before","explanation":"Ghi nhớ công thức: 'This is the first time + S + have/has + PII' = 'S + have/has never + PII + before', cùng diễn tả một trải nghiệm chưa từng xảy ra trước đây. Câu gốc có 'I have used', ta giữ nguyên và chỉ thêm 'never' sau 'have' cùng 'before' ở cuối câu. Đáp án đầy đủ: 'I have never used a self-checkout machine at the supermarket before.'"},
  {"id":"rw-188","cat":"first-time","catLabel":"This is the first time ↔ have never ... before","orig":"This is the first time the students have submitted their homework online.","stem":"The students have never","answer":"submitted their homework online before","accept":["submitted their homework online before","submitted their homework online"],"vi":"'This is the first time' + HTHT ↔ 'have/has never' + PII + before","explanation":"Đây là dạng chuyển đổi quen thuộc: 'This is the first time' + hiện tại hoàn thành → 'never...before' + hiện tại hoàn thành, hai cách diễn đạt tương đương về nghĩa. Chủ ngữ số nhiều 'the students' đi với 'have', cụm 'submitted their homework online' được giữ nguyên dạng phân từ hai. Đáp án đầy đủ: 'The students have never submitted their homework online before.'"},
  {"id":"rw-189","cat":"first-time","catLabel":"This is the first time ↔ have never ... before","orig":"This is the first time my parents have traveled abroad by plane.","stem":"My parents have never","answer":"traveled abroad by plane before","accept":["traveled abroad by plane before","traveled abroad by plane","travelled abroad by plane before","travelled abroad by plane"],"vi":"'This is the first time' + HTHT ↔ 'have/has never' + PII + before","explanation":"Công thức cần nhớ: 'This is the first time + S + have/has + PII' ↔ 'S + have/has never + PII + before'. Với chủ ngữ số nhiều 'my parents', động từ chia 'have traveled', ta chỉ việc thêm 'never' sau 'have' và 'before' ở cuối câu. Đáp án đầy đủ: 'My parents have never traveled abroad by plane before.' (traveled/travelled đều đúng, theo Anh-Mỹ/Anh-Anh)."},
  {"id":"rw-190","cat":"first-time","catLabel":"This is the first time ↔ have never ... before","orig":"This is the first time he has been late for an important job interview.","stem":"He has never","answer":"been late for an important job interview before","accept":["been late for an important job interview before","been late for an important job interview"],"vi":"'This is the first time' + HTHT ↔ 'have/has never' + PII + before","explanation":"Lưu ý câu này dùng 'has been' (động từ to be ở hiện tại hoàn thành), khi chuyển đổi vẫn áp dụng đúng công thức 'S + have/has never + PII + before', không đổi cấu trúc động từ. Ta giữ nguyên 'late for an important job interview' và chỉ thêm 'never' sau 'has', 'before' ở cuối câu. Đáp án đầy đủ: 'He has never been late for an important job interview before.'"},
  {"id":"rw-191","cat":"first-time","catLabel":"This is the first time ↔ have never ... before","orig":"This is the first time the local team has won the national football championship.","stem":"The local team has never","answer":"won the national football championship before","accept":["won the national football championship before","won the national football championship"],"vi":"'This is the first time' + HTHT ↔ 'have/has never' + PII + before","explanation":"Câu này có tân ngữ dài (the national football championship) nhưng công thức chuyển đổi vẫn không đổi: 'This is the first time + S + have/has + PII + O' = 'S + have/has never + PII + O + before'. Giữ nguyên toàn bộ phần còn lại của câu, chỉ thêm 'never' và 'before'. Đáp án đầy đủ: 'The local team has never won the national football championship before.'"},
  {"id":"rw-192","cat":"first-time","catLabel":"This is the first time ↔ have never ... before","orig":"This is the first time I have had to make such a difficult decision on my own.","stem":"I have never","answer":"had to make such a difficult decision on my own before","accept":["had to make such a difficult decision on my own before","had to make such a difficult decision on my own"],"vi":"'This is the first time' + HTHT ↔ 'have/has never' + PII + before","explanation":"Câu khó hơn vì có cấu trúc 'have had to + V-nguyên thể' (đã phải làm gì đó), nhưng nguyên tắc chuyển đổi vẫn giữ nguyên: chỉ thêm 'never' ngay sau 'have' và 'before' ở cuối câu, không thay đổi các thành phần còn lại. Đáp án đầy đủ: 'I have never had to make such a difficult decision on my own before.'"},
  {"id":"rw-193","cat":"belong-to","catLabel":"Belong to ↔ sở hữu (own / possessive)","orig":"This smartphone belongs to my cousin.","stem":"This is","answer":"my cousin's smartphone","accept":["my cousin's smartphone","my cousins smartphone","the smartphone that belongs to my cousin"],"vi":"belong to + danh từ số ít (người) ↔ thêm 's","explanation":"Công thức: \"S (vật) + belongs to + N (người số ít)\" ↔ \"This/That + is/are + N (người)'s + N (vật)\". Với danh từ chỉ người số ít không tận cùng -s, ta thêm 's ngay sau danh từ đó. Ở đây \"belongs to my cousin\" chuyển thành \"my cousin's smartphone\". Đáp án đầy đủ: This is my cousin's smartphone."},
  {"id":"rw-194","cat":"belong-to","catLabel":"Belong to ↔ sở hữu (own / possessive)","orig":"These umbrellas belong to the teachers.","stem":"These are","answer":"the teachers' umbrellas","accept":["the teachers' umbrellas","the teachers umbrellas","the umbrellas that belong to the teachers"],"vi":"belong to + danh từ số nhiều tận -s ↔ chỉ thêm dấu nháy đơn (')","explanation":"Khi danh từ chỉ người ở số nhiều đã có đuôi -s (teachers), sở hữu cách chỉ cần thêm dấu nháy đơn (') ngay sau -s, không thêm 's nữa. Câu gốc \"belong to the teachers\" chuyển thành sở hữu cách \"the teachers' umbrellas\". Đáp án đầy đủ: These are the teachers' umbrellas."},
  {"id":"rw-195","cat":"belong-to","catLabel":"Belong to ↔ sở hữu (own / possessive)","orig":"These toys belong to the children.","stem":"These are","answer":"the children's toys","accept":["the children's toys","the childrens toys","the toys that belong to the children"],"vi":"belong to + danh từ số nhiều bất quy tắc (children, people...) ↔ vẫn thêm 's","explanation":"Một số danh từ số nhiều không tận cùng bằng -s (children, men, women, people) vẫn theo quy tắc như danh từ số ít: thêm 's để chỉ sở hữu, KHÁC với \"teachers\" (chỉ thêm dấu nháy đơn). Vậy \"belong to the children\" chuyển thành \"the children's toys\". Đáp án đầy đủ: These are the children's toys."},
  {"id":"rw-196","cat":"belong-to","catLabel":"Belong to ↔ sở hữu (own / possessive)","orig":"This painting belongs to my boss.","stem":"This is","answer":"my boss's painting","accept":["my boss's painting","my bosss painting","my boss' painting"],"vi":"danh từ số ít tận -s ↔ vẫn thêm 's","explanation":"Lưu ý: danh từ số ít dù đã tận cùng bằng -s (boss) vẫn thêm 's để chỉ sở hữu (đọc là /ɪz/), khác với danh từ số nhiều chỉ thêm dấu nháy đơn. Vậy \"belongs to my boss\" chuyển thành \"my boss's painting\". Đáp án đầy đủ: This is my boss's painting."},
  {"id":"rw-197","cat":"belong-to","catLabel":"Belong to ↔ sở hữu (own / possessive)","orig":"That is Mai's guitar.","stem":"That guitar","answer":"belongs to Mai","accept":["belongs to mai","is owned by mai"],"vi":"sở hữu cách 's ↔ belong to (đổi chiều)","explanation":"Chiều ngược lại của cấu trúc: \"N (người)'s + N (vật)\" ↔ \"N (vật) + belongs to + N (người)\". Câu gốc có sở hữu cách \"Mai's guitar\", nên chuyển thành \"That guitar belongs to Mai\". Đáp án đầy đủ: That guitar belongs to Mai."},
  {"id":"rw-198","cat":"belong-to","catLabel":"Belong to ↔ sở hữu (own / possessive)","orig":"This tablet belongs to us.","stem":"This tablet is","answer":"ours","accept":["ours"],"vi":"belong to + đại từ ↔ đại từ sở hữu (ours/theirs...)","explanation":"Khi tân ngữ sau \"belong to\" là đại từ chỉ người (us, them, her...), ta đổi thành đại từ sở hữu tuyệt đối tương ứng, đứng một mình không kèm danh từ phía sau: us → ours. Câu \"This tablet belongs to us\" chuyển thành \"This tablet is ours\". Đáp án đầy đủ: This tablet is ours."},
  {"id":"rw-199","cat":"belong-to","catLabel":"Belong to ↔ sở hữu (own / possessive)","orig":"This land belongs to the local government.","stem":"This land is the property","answer":"of the local government","accept":["of the local government"],"vi":"belong to (tổ chức) ↔ be the property of","explanation":"Khi chủ sở hữu là một tổ chức/tập thể (the local government) chứ không phải một cá nhân, ta có thể diễn đạt lại bằng cấu trúc \"be the property of + N\" thay cho \"belong to\". Câu gốc \"belongs to the local government\" chuyển thành \"is the property of the local government\". Đáp án đầy đủ: This land is the property of the local government."},
  {"id":"rw-200","cat":"belong-to","catLabel":"Belong to ↔ sở hữu (own / possessive)","orig":"This restaurant belongs to Mr. Hung.","stem":"Mr. Hung","answer":"owns this restaurant","accept":["owns this restaurant","owns the restaurant"],"vi":"belong to ↔ own (đổi chủ ngữ thành người sở hữu)","explanation":"Cấu trúc \"N (vật) + belongs to + N (người)\" có thể viết lại bằng động từ \"own\", với chủ ngữ đổi thành chính người sở hữu: \"N (người) + owns + N (vật)\". Câu \"This restaurant belongs to Mr. Hung\" chuyển thành \"Mr. Hung owns this restaurant\". Đáp án đầy đủ: Mr. Hung owns this restaurant."}
];

if (typeof module !== 'undefined' && module.exports) { module.exports = { REWRITE_QUESTIONS }; }
